const releaseBody = "WEBVTT\nX-TIMESTAMP-MAP=MPEGTS:900000,LOCAL:00:00:00.000\n\nSTYLE\n::cue(.styledotitalic) { font-style:italic }\n::cue(.styledotdefault) { background-color:transparent }\n\n9901803\n00:01:04.530 --> 00:01:06.610 align:middle line:85%,start position:50%,middle\nGitHub：rexchen1803\n\n1\n00:01:06.690 --> 00:01:11.200 align:middle line:85%,start position:50%,middle\n1805年4月 拿破仑主宰着欧洲\n\n2\n00:01:11.210 --> 00:01:16.570 align:middle line:85%,start position:50%,middle\n唯有英国舰队与之匹敌 海洋化为了战场\n\n3\n00:01:53.940 --> 00:02:01.200 align:middle line:85%,start position:50%,middle\n《怒海争锋：极地远征》\n\n4\n00:02:07.710 --> 00:02:10.510 align:middle line:85%,start position:50%,middle\n英国皇家海军战舰——“惊奇”号\n\n5\n00:02:10.510 --> 00:02:14.250 align:middle line:85%,start position:50%,middle\n主炮28门 载员197人 巴西北部海岸\n\n6\n00:02:16.050 --> 00:02:23.620 align:middle line:85%,start position:50%,middle\n英国海军部授命杰克·奥布里船长：\n拦截驶向太平洋的法国私掠舰“地狱神”号\n\n7\n00:02:23.620 --> 00:02:29.560 align:middle line:85%,start position:50%,middle\n该舰意图将战争引向太平洋\n你们可以击沉、焚烧或者俘获它\n\n8\n00:04:16.673 --> 00:04:20.719 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>过来 过来 很好</c>\n\n9\n00:04:20.802 --> 00:04:23.013 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>对 对 好了</c>\n\n10\n00:04:30.854 --> 00:04:33.065 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>醒醒 威尔</c>\n\n11\n00:04:39.530 --> 00:04:42.074 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>船首右侧发现情况！</c>\n\n12\n00:04:50.499 --> 00:04:51.540 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>什么情况 斯莱德？</c>\n\n13\n00:04:51.540 --> 00:04:53.001 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我好像听到了什么声音</c>\n\n14\n00:04:53.085 --> 00:04:55.170 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>像是信号钟的声音</c>\n\n15\n00:04:56.755 --> 00:04:58.370 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>可能是当地渔民</c>\n\n16\n00:04:58.370 --> 00:05:00.968 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>或者是暗礁标志 长官</c>\n\n17\n00:05:01.051 --> 00:05:04.012 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>卡拉米先生 可以的话 用铅锤测一下水深</c>\n\n18\n00:05:18.944 --> 00:05:23.073 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 刻度上显示 5英寻\n- 5英寻！</c>\n\n19\n00:05:37.296 --> 00:05:40.549 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 都是沙和碎贝壳\n- 都是沙和碎贝壳</c>\n\n20\n00:05:47.431 --> 00:05:49.725 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是什么？</c>\n\n21\n00:05:49.800 --> 00:05:51.720 align:middle line:85%,start position:50%,middle\n嗯…\n\n22\n00:05:51.810 --> 00:05:54.479 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>右前方两个罗经点处 浓雾里面</c>\n\n23\n00:05:54.563 --> 00:05:56.565 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>什么？是一艘船？</c>\n\n24\n00:05:56.648 --> 00:05:58.140 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不知道是什么</c>\n\n25\n00:05:58.140 --> 00:06:01.153 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我们应该进入战备状态吗？</c>\n\n26\n00:06:08.410 --> 00:06:12.831 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 我也不是很肯定\n- 你是当值官</c>\n\n27\n00:06:12.915 --> 00:06:15.918 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>霍伦 你得下个决定</c>\n\n28\n00:06:17.419 --> 00:06:19.671 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>进入战备状态！</c>\n\n29\n00:06:21.924 --> 00:06:25.052 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>起来！起来！睡觉的人都醒醒！</c>\n\n30\n00:06:29.348 --> 00:06:31.433 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>动起来！快！快！</c>\n\n31\n00:06:31.517 --> 00:06:34.603 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>快点 伙计们！快点！</c>\n\n32\n00:06:36.104 --> 00:06:37.981 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>把帆索顺过去！</c>\n\n33\n00:06:59.795 --> 00:07:01.421 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>长官 浓雾里有情况</c>\n\n34\n00:07:01.505 --> 00:07:05.050 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 稳稳拉紧帆桁滑车！\n- 桅楼手上桅！</c>\n\n35\n00:07:13.851 --> 00:07:16.103 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 在哪儿？\n- 呃…</c>\n\n36\n00:07:16.186 --> 00:07:20.983 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>右前方两个罗经点处 长官 不到一英里远</c>\n\n37\n00:07:23.861 --> 00:07:26.822 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 你确信吗 霍伦先生？\n- 确信 长官</c>\n\n38\n00:07:28.198 --> 00:07:30.325 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是军舰？</c>\n\n39\n00:07:32.327 --> 00:07:34.162 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不知道 长官</c>\n\n40\n00:07:34.246 --> 00:07:38.083 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>片刻就消失了 但我想我看见了轮廓</c>\n\n41\n00:07:41.003 --> 00:07:44.256 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 你看到了吗 卡拉米先生？\n- 没有 长官</c>\n\n42\n00:07:46.383 --> 00:07:51.054 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>呃 你做的对 霍伦先生 回你们岗位去吧</c>\n\n43\n00:07:52.514 --> 00:07:54.933 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>甲板交给你了 汤姆</c>\n\n44\n00:07:55.017 --> 00:07:56.435 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是的 长官</c>\n\n45\n00:07:58.937 --> 00:08:02.691 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>清理一下！把小船放下去！</c>\n\n46\n00:08:10.782 --> 00:08:13.535 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 别无所事事！\n- 听到了吗！</c>\n\n47\n00:08:13.619 --> 00:08:16.038 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>放下小船！</c>\n\n48\n00:08:18.740 --> 00:08:20.080 align:middle line:85%,start position:50%,middle\n用力拉帆桁上的索具！\n\n49\n00:08:25.380 --> 00:08:27.090 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>敲信号钟！</c>\n\n50\n00:08:54.326 --> 00:08:56.662 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>趴下！都趴下！</c>\n\n51\n00:09:11.134 --> 00:09:15.180 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>回你们的岗位上去！\n霍勒先生 劳驾作个损坏报告</c>\n\n52\n00:09:24.356 --> 00:09:28.193 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>至少是18磅炮，长官！\n靠近些，推出右舷炮组！</c>\n\n53\n00:09:28.277 --> 00:09:32.030 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>艾伦先生，迎风转向！\n贴到手枪射程内！</c>\n\n54\n00:09:38.245 --> 00:09:40.539 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>叫神枪手去桅楼，霍华德先生</c>\n\n55\n00:09:40.622 --> 00:09:43.208 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>中士！带你的人去主桅楼！</c>\n\n56\n00:09:43.292 --> 00:09:46.170 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>在后甲板挺直腰板，孩子\n所有人都要挺住</c>\n\n57\n00:09:47.337 --> 00:09:50.257 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 波义耳先生 升舰旗！\n- 是 先生</c>\n\n58\n00:09:55.304 --> 00:09:57.160 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>航行日志里这样记录 瓦特先生</c>\n\n59\n00:09:57.160 --> 00:09:59.308 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>“打六响钟时，与敌方巡防舰交战”</c>\n\n60\n00:10:03.770 --> 00:10:06.398 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 瞄准他们 莫威先生\n- 瞄准了 长官</c>\n\n61\n00:10:06.481 --> 00:10:08.901 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>比尔！</c>\n\n62\n00:10:08.984 --> 00:10:11.862 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>别管这些剑了！拿下面船长的银器</c>\n\n63\n00:10:11.945 --> 00:10:15.991 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>还不在射程内！继续前进直到她进入射程！</c>\n\n64\n00:10:16.074 --> 00:10:19.870 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 贴紧其舰舯！\n- 正对舰舯，长官！</c>\n\n65\n00:10:20.579 --> 00:10:22.873 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>上帝 别掉了什么！</c>\n\n66\n00:10:28.212 --> 00:10:29.421 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>稳住！</c>\n\n67\n00:10:29.505 --> 00:10:33.008 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 坚守岗位！\n- 坚守岗位！拿出勇气来！</c>\n\n68\n00:10:34.176 --> 00:10:35.430 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>稳住 伙计们！</c>\n\n69\n00:10:35.430 --> 00:10:38.514 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>别担心 伙计们 我们要开始报复了！</c>\n\n70\n00:10:38.597 --> 00:10:40.150 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是普灵斯先生，长官</c>\n\n71\n00:10:40.160 --> 00:10:42.976 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>戴维斯、杰米，把普灵斯先生抬到下面去</c>\n\n72\n00:10:43.060 --> 00:10:44.770 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是 长官</c>\n\n73\n00:10:44.853 --> 00:10:47.356 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>布莱克尼先生 传达船长命令</c>\n\n74\n00:10:47.439 --> 00:10:50.150 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>清除前方的系索杆！</c>\n\n75\n00:10:56.615 --> 00:10:58.200 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>再往地上撒些沙！</c>\n\n76\n00:10:59.868 --> 00:11:01.662 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>趁船身上仰时…开火！</c>\n\n77\n00:11:14.925 --> 00:11:16.552 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>趴下！</c>\n\n78\n00:11:25.561 --> 00:11:30.065 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>装上舵柄应急滑车！\n你们几个，去救伤员！</c>\n\n79\n00:11:32.276 --> 00:11:34.050 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>保持连续开火，卡拉米先生</c>\n\n80\n00:11:34.050 --> 00:11:37.281 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是 长官 再次填弹 送他们去西天！</c>\n\n81\n00:12:03.473 --> 00:12:05.726 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>长官！到船尾去！</c>\n\n82\n00:12:12.316 --> 00:12:15.402 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>船舵被打掉了 无法导航了 长官</c>\n\n83\n00:12:15.485 --> 00:12:17.738 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>成瓮中之鳖了</c>\n\n84\n00:12:25.037 --> 00:12:27.372 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我们怎么不开火？</c>\n\n85\n00:12:31.835 --> 00:12:33.295 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>让我过去</c>\n\n86\n00:12:33.378 --> 00:12:35.923 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>这里 乔！这里！</c>\n\n87\n00:12:36.006 --> 00:12:38.133 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>那儿要稳住！</c>\n\n88\n00:12:42.554 --> 00:12:44.670 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>他在船首左舷 长官</c>\n\n89\n00:12:44.670 --> 00:12:47.559 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>拿出你们的轻武器来！</c>\n\n90\n00:12:50.646 --> 00:12:53.148 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>准备击退跳帮敌军！</c>\n\n91\n00:12:53.232 --> 00:12:56.360 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>拿好武器候命！</c>\n\n92\n00:12:58.487 --> 00:13:00.822 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>请下令 长官？</c>\n\n93\n00:13:01.823 --> 00:13:06.161 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>召集所有炮手来甲板\n用缆绳从船尾将小船都放下去</c>\n\n94\n00:13:06.245 --> 00:13:08.830 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>然后把我们拖进雾里 汤姆</c>\n\n95\n00:13:19.800 --> 00:13:22.344 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>一起拉 兄弟们！</c>\n\n96\n00:13:22.427 --> 00:13:24.513 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>往雾里拉！</c>\n\n97\n00:13:25.931 --> 00:13:28.517 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>推出炮门！全部推出！</c>\n\n98\n00:13:32.855 --> 00:13:34.481 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>开火！</c>\n\n99\n00:13:35.858 --> 00:13:39.862 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>出现一条裂缝！我们得用麻絮堵上</c>\n\n100\n00:13:39.945 --> 00:13:42.698 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>乔 拿锤子和铁钉来！</c>\n\n101\n00:13:48.620 --> 00:13:50.789 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>她正朝我们逼近</c>\n\n102\n00:13:57.963 --> 00:13:59.840 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我们快到了 兄弟们！</c>\n\n103\n00:13:59.840 --> 00:14:01.884 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>拉呀！用力拉呀！</c>\n\n104\n00:14:01.967 --> 00:14:03.250 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>快到了 兄弟们！</c>\n\n105\n00:14:03.250 --> 00:14:05.137 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>在雾里我们就安全了！</c>\n\n106\n00:14:09.933 --> 00:14:11.226 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>开火！</c>\n\n107\n00:14:12.853 --> 00:14:15.814 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>为了福星高照的杰克 用力拉吧！</c>\n\n108\n00:14:15.898 --> 00:14:18.066 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我们成功了！</c>\n\n109\n00:14:20.360 --> 00:14:23.238 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>安静 甲板上安静下来</c>\n\n110\n00:14:33.123 --> 00:14:36.251 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我们在这儿不会被他们发现！</c>\n\n111\n00:14:36.335 --> 00:14:39.963 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>安静 伙计们 别喊 也别叫唤</c>\n\n112\n00:15:07.950 --> 00:15:10.160 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不划了</c>\n\n113\n00:15:13.121 --> 00:15:15.499 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>干得好 伙计们</c>\n\n114\n00:15:39.523 --> 00:15:42.818 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>水进了2英尺半深 长官…控制住了</c>\n\n115\n00:15:46.488 --> 00:15:49.199 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 干得好 兰姆先生\n- 谢谢 长官</c>\n\n116\n00:15:59.835 --> 00:16:01.962 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>死伤情况如何？</c>\n\n117\n00:16:02.045 --> 00:16:04.673 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>9人死亡 27人受伤</c>\n\n118\n00:16:13.891 --> 00:16:15.350 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>乔·普莱斯</c>\n\n119\n00:16:15.434 --> 00:16:20.772 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>他的头颅严重破裂 我想他活不过今晚</c>\n\n120\n00:16:20.856 --> 00:16:23.609 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>布莱克尼阁下</c>\n\n121\n00:16:26.028 --> 00:16:28.363 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>手断了而已 长官</c>\n\n122\n00:16:29.615 --> 00:16:32.576 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>呃 你会得到很好的照顾</c>\n\n123\n00:16:37.289 --> 00:16:40.876 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我尽全力了 我知道你和他父亲熟识</c>\n\n124\n00:16:40.959 --> 00:16:45.339 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>他父亲会理解的 他了解这种生活 但他母亲…</c>\n\n125\n00:16:45.422 --> 00:16:48.967 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>让我看看你的眉毛</c>\n\n126\n00:16:49.051 --> 00:16:50.886 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>怎么了？</c>\n\n127\n00:16:55.641 --> 00:16:58.727 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>该死 敌军真厉害 不知道从哪儿</c>\n\n128\n00:16:58.810 --> 00:17:03.982 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>袭击我们舷侧 绕到我们后面 打掉了我们的船舵</c>\n\n129\n00:17:04.066 --> 00:17:06.276 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>这精良的炮术真该死</c>\n\n130\n00:17:07.236 --> 00:17:11.906 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>都是由于浓雾 我们才侥幸逃脱 太幸运了 真的</c>\n\n131\n00:17:11.990 --> 00:17:16.744 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>也许他们占据上风 但是我们有老天相助</c>\n\n132\n00:17:17.788 --> 00:17:23.585 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我搞不懂你说得什么 但好像敌军干得很棒</c>\n\n133\n00:17:24.586 --> 00:17:29.842 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>航行了七个礼拜 他们却准确地找到了我们位置</c>\n\n134\n00:17:29.919 --> 00:17:32.129 align:middle line:85%,start position:50%,middle\n嗯\n\n135\n00:17:32.261 --> 00:17:36.348 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>呃 法国在英国及其他地方都派有间谍\n和我们一样</c>\n\n136\n00:17:37.015 --> 00:17:38.934 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>的确如此</c>\n\n137\n00:17:40.102 --> 00:17:43.139 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>如果敌人知道我们是冲着他们来的</c>\n\n138\n00:17:43.139 --> 00:17:46.191 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>他们大可驶入大海 隐藏得很好</c>\n\n139\n00:17:46.275 --> 00:17:49.444 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>呃…那么 可能他们也是冲着我们来的</c>\n\n140\n00:18:15.637 --> 00:18:18.223 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>巡防舰？她要是巡防舰\n那我就是荷兰人！</c>\n\n141\n00:18:18.307 --> 00:18:21.226 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>这很不公平 没什么丢脸的</c>\n\n142\n00:18:21.310 --> 00:18:23.562 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>敌方更像是战列舰</c>\n\n143\n00:18:23.645 --> 00:18:26.982 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你们应该留意她的船体 我们的炮弹无法打穿</c>\n\n144\n00:18:27.065 --> 00:18:29.693 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>200码外填装三倍弹丸\n火炮也毫无效果</c>\n\n145\n00:18:29.776 --> 00:18:33.572 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>敌方处于上风 在火力上又有明显的优势</c>\n\n146\n00:18:33.655 --> 00:18:36.200 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>什么处于上风？</c>\n\n147\n00:18:36.283 --> 00:18:38.299 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>要我在给你讲一遍吗 斯蒂芬？</c>\n\n148\n00:18:38.299 --> 00:18:39.786 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>别在桌布上写！</c>\n\n149\n00:18:41.914 --> 00:18:46.084 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>就是说 风向对他们有利\n因此交战时易于控制局势</c>\n\n150\n00:18:46.168 --> 00:18:49.421 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>还有 他们射程更远\n所以能在我们射程外攻击我们</c>\n\n151\n00:18:49.505 --> 00:18:53.175 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>很明显 我们被打得很惨</c>\n\n152\n00:18:55.636 --> 00:18:57.804 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>太平洋里这样的重型护卫舰…</c>\n\n153\n00:18:57.888 --> 00:19:00.724 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>会让战争的天平向拿破仑倾斜</c>\n\n154\n00:19:01.350 --> 00:19:06.355 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>相比之下，“惊奇”号\n是艘有些年迈的战舰</c>\n\n155\n00:19:10.108 --> 00:19:14.947 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 我说的不对吗？\n- 你称我为年迈的战士？</c>\n\n156\n00:19:15.030 --> 00:19:18.325 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>“惊奇”号并不年迈\n没人能说她年迈</c>\n\n157\n00:19:18.408 --> 00:19:21.049 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>她船艏饱满，线条优美</c>\n\n158\n00:19:21.049 --> 00:19:24.581 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>她是只优秀的海鸟\n迎风稳健，航速飞快</c>\n\n159\n00:19:24.665 --> 00:19:28.043 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>很神速 如果操纵得当</c>\n\n160\n00:19:28.126 --> 00:19:30.254 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不 一点也不年迈</c>\n\n161\n00:19:31.547 --> 00:19:33.632 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>正值年富力强之时</c>\n\n162\n00:19:33.715 --> 00:19:35.389 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我们可以修好主桅以及后桅</c>\n\n163\n00:19:35.389 --> 00:19:38.262 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>前桅的大帆也不能用了 我们只好用备用的</c>\n\n164\n00:19:38.345 --> 00:19:42.432 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>兰姆先生对常规修补很自信 我们能如期返航</c>\n\n165\n00:19:42.516 --> 00:19:45.310 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我们不会返航</c>\n\n166\n00:19:54.278 --> 00:19:56.039 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>但我们得找个港口来整修</c>\n\n167\n00:19:56.039 --> 00:19:58.490 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>“地狱神”号也许还在搜寻我们</c>\n\n168\n00:19:58.574 --> 00:20:02.828 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我们可以在海上整修 就在这儿 浅滩上</c>\n\n169\n00:20:04.079 --> 00:20:06.449 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>如你所说 艾伦先生 她会将战争</c>\n\n170\n00:20:06.449 --> 00:20:08.792 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>引入南部海域 我们要去阻止她</c>\n\n171\n00:20:08.876 --> 00:20:16.169 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>但长官 要知道她可是重型\n战舰级别远在我们之上</c>\n\n172\n00:20:17.092 --> 00:20:20.846 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我们整修完毕之前 她就已经驶往合恩角了</c>\n\n173\n00:20:20.929 --> 00:20:24.641 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>那么 我们不能再浪费时间了</c>\n\n174\n00:20:42.993 --> 00:20:46.205 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>最后一针穿过你鼻子 是真的吗？</c>\n\n175\n00:20:46.288 --> 00:20:48.332 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你是说？</c>\n\n176\n00:20:49.374 --> 00:20:54.713 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>乔说 临死的时候 最后一针会将鼻子缝在吊床上</c>\n\n177\n00:20:54.796 --> 00:20:57.966 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>为确信你并非睡着</c>\n\n178\n00:21:01.637 --> 00:21:05.057 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>别刺穿我鼻子 你能给他们讲讲吗？</c>\n\n179\n00:22:01.780 --> 00:22:06.285 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>没事的 这只是鸦片酊的缘故</c>\n\n180\n00:22:39.902 --> 00:22:42.613 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我从未见过比你更加勇敢的病人</c>\n\n181\n00:22:47.492 --> 00:22:51.538 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>可怜的孩子，别担心\n很快就给你处理好</c>\n\n182\n00:22:51.622 --> 00:22:53.582 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我希望看到优秀的工作成果</c>\n\n183\n00:22:53.665 --> 00:22:58.170 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>需要两个人到右舷前舱去 罗伯特 查德威</c>\n\n184\n00:22:58.253 --> 00:23:00.339 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>干得很棒</c>\n\n185\n00:23:00.422 --> 00:23:03.675 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>这里不要修了 我要换掉</c>\n\n186\n00:23:10.432 --> 00:23:13.769 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>卡拉米先生 你或许对这个感兴趣</c>\n\n187\n00:23:13.852 --> 00:23:18.440 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>看，这是船长刻的\n当时他还是见习军官，比你还小</c>\n\n188\n00:23:18.524 --> 00:23:20.400 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>他从小就对这艘船了如指掌</c>\n\n189\n00:23:20.484 --> 00:23:25.697 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>他说雕刻时流的血\n足以让这艘船和他有血缘关系</c>\n\n190\n00:23:25.781 --> 00:23:30.035 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我完全明白你的意思\n艾伦先生 你的学识毋庸质疑</c>\n\n191\n00:23:30.118 --> 00:23:33.399 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>但是 在巴西的热带雨林呆上一个礼拜</c>\n\n192\n00:23:33.409 --> 00:23:35.541 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>去找根新桅杆根本行不通</c>\n\n193\n00:23:35.624 --> 00:23:37.876 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>“地狱神”号将会驶往中国</c>\n\n194\n00:23:37.960 --> 00:23:41.149 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>和往常一样 兰姆先生会尽全力的</c>\n\n195\n00:23:41.149 --> 00:23:43.674 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>这也是我对所有人的期待</c>\n\n196\n00:24:17.749 --> 00:24:19.585 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是脑浆吗？</c>\n\n197\n00:24:19.668 --> 00:24:23.463 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不是 只是血块 这才是脑浆</c>\n\n198\n00:24:28.844 --> 00:24:32.139 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>他是内科医生 不是一般的外科医生</c>\n\n199\n00:24:32.222 --> 00:24:35.392 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 硬币递给我 好吗？\n- 先生</c>\n\n200\n00:24:40.147 --> 00:24:42.941 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>在岸上少于十畿尼\n他连看都不会看你</c>\n\n201\n00:24:43.025 --> 00:24:45.152 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>而且他也对鸟兽了如指掌</c>\n\n202\n00:24:45.235 --> 00:24:48.614 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>给他一只甲虫 他就会告诉你 那甲虫在想什么</c>\n\n203\n00:24:48.697 --> 00:24:52.242 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>回去工作 你们这些懒汉！厄哈特 吹口哨</c>\n\n204\n00:24:52.326 --> 00:24:54.786 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我们继续 先生们</c>\n\n205\n00:24:54.870 --> 00:24:58.624 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你们在这儿看也没有用！</c>\n\n206\n00:25:05.214 --> 00:25:07.799 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>仍然没有醒 长官</c>\n\n207\n00:25:13.222 --> 00:25:16.225 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>布莱克尼阁下 好些了吗？</c>\n\n208\n00:25:16.308 --> 00:25:18.393 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>好多了 谢谢 长官</c>\n\n209\n00:25:18.477 --> 00:25:20.562 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>嗯 很好 很好</c>\n\n210\n00:25:22.439 --> 00:25:26.527 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>医生告诉我 你喜欢看书 我就…</c>\n\n211\n00:25:28.559 --> 00:25:32.819 align:middle line:85%,start position:50%,middle\n霍雷肖子爵阁下 纳尔逊的胜利\n勇敢的不列颠英雄\n\n212\n00:25:32.824 --> 00:25:36.286 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>里面囊括了他所有主要的战役\n还附有精美的插图</c>\n\n213\n00:25:36.370 --> 00:25:38.288 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>谢谢 长官</c>\n\n214\n00:25:39.581 --> 00:25:42.167 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你见过纳尔逊勋爵吗，长官？</c>\n\n215\n00:25:42.251 --> 00:25:43.769 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我很荣幸和他一起服兵役</c>\n\n216\n00:25:43.769 --> 00:25:45.921 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>在尼罗河 赢了一个伟大的胜利</c>\n\n217\n00:25:46.004 --> 00:25:49.159 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>事实上 你可以在这儿找到</c>\n\n218\n00:25:49.169 --> 00:25:52.094 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>没搞错的话 在第135页</c>\n\n219\n00:25:53.512 --> 00:25:55.430 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是的</c>\n\n220\n00:26:01.311 --> 00:26:05.190 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>能劳驾你给我讲讲 他是怎么样的人？</c>\n\n221\n00:26:07.442 --> 00:26:09.403 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你应该看这本书的</c>\n\n222\n00:26:09.486 --> 00:26:12.114 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我会的 长官 谢谢你</c>\n\n223\n00:26:32.801 --> 00:26:37.890 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>又开始了 吱吱嘎嘎的声音</c>\n\n224\n00:26:37.973 --> 00:26:41.852 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>这种调子根本不能跳舞\n除非醉得像戴维家的母猪</c>\n\n225\n00:26:51.820 --> 00:26:53.614 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>这一曲怎么样？</c>\n\n226\n00:26:53.697 --> 00:26:58.160 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>或者有心情来点更加激情的？</c>\n\n227\n00:28:11.525 --> 00:28:13.694 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>敬礼</c>\n\n228\n00:28:13.777 --> 00:28:15.654 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>脱帽</c>\n\n229\n00:28:17.906 --> 00:28:20.075 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>怎么了？</c>\n\n230\n00:28:22.786 --> 00:28:26.164 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 什么？\n- “幽灵” 长官</c>\n\n231\n00:28:26.248 --> 00:28:30.002 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>抱歉 伙计们这样叫他 “地狱神”号 长官</c>\n\n232\n00:28:30.085 --> 00:28:33.005 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>瞧 威尔就在这儿 他目睹了造船的全过程</c>\n\n233\n00:28:33.088 --> 00:28:38.260 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是在波士顿 长官 和平时期美国佬造的 长官</c>\n\n234\n00:28:38.343 --> 00:28:42.264 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>他正结婚 他老婆的堂兄就在造船厂工作</c>\n\n235\n00:28:42.347 --> 00:28:44.600 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>所以威尔是看着这艘船被造出来</c>\n\n236\n00:28:44.683 --> 00:28:49.938 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>长官 我发现有些很奇怪的地方 所以就问乔…</c>\n\n237\n00:28:50.022 --> 00:28:53.358 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>他便向我描述 我就为你作成了这个模型 长官</c>\n\n238\n00:28:53.442 --> 00:28:58.197 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 这个模型很精确啰？\n- 绝对精确 长官</c>\n\n239\n00:28:58.280 --> 00:29:00.866 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 谢谢 伙计们\n- 谢谢 长官</c>\n\n240\n00:29:00.949 --> 00:29:04.161 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>奇利克，给弟兄们\n多发一份朗姆酒</c>\n\n241\n00:29:04.244 --> 00:29:06.705 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>非常感谢 长官</c>\n\n242\n00:29:06.788 --> 00:29:08.189 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>这可是我留着敬礼日用的</c>\n\n243\n00:29:08.189 --> 00:29:09.750 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>到时候我们喝葡萄酒</c>\n\n244\n00:29:09.833 --> 00:29:11.960 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>噢 敬礼日喝红酒…</c>\n\n245\n00:29:12.044 --> 00:29:14.713 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>水上部分宽而直 水下部分尖而利</c>\n\n246\n00:29:14.796 --> 00:29:20.209 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>船体能更好地入水 且尾部修长\n这就是神速的原因</c>\n\n247\n00:29:20.302 --> 00:29:22.971 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>船更重了 但一样神速</c>\n\n248\n00:29:23.972 --> 00:29:29.311 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>这就是船的未来 我们生活的时代多么现代化啊</c>\n\n249\n00:29:29.394 --> 00:29:33.273 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>肋骨和外板让船体厚达2英尺\n全是实心橡木</c>\n\n250\n00:29:33.357 --> 00:29:35.659 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>这就是我们不能破坏她的原因</c>\n\n251\n00:29:35.659 --> 00:29:38.278 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>她的速度可能达到12到14节</c>\n\n252\n00:29:38.987 --> 00:29:42.324 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>现在我们明白了\n真得感谢沃利和他妻子的堂兄啊</c>\n\n253\n00:29:42.407 --> 00:29:45.369 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>她每天可以航行280英里</c>\n\n254\n00:29:45.452 --> 00:29:51.500 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>即使我们真能追上…我是说 咬住她…</c>\n\n255\n00:29:51.583 --> 00:29:55.712 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我们也和她不是一个档次 她有44门炮</c>\n\n256\n00:29:57.339 --> 00:30:01.760 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>但船尾仍不堪一击 和其他船一样</c>\n\n257\n00:30:15.524 --> 00:30:18.485 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>嗨 亲爱的！吻一下要多少钱？</c>\n\n258\n00:30:19.278 --> 00:30:21.321 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>吻一下要多少钱？</c>\n\n259\n00:30:21.405 --> 00:30:24.616 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 什么名字？\n- 我叫玛利亚</c>\n\n260\n00:30:24.700 --> 00:30:27.995 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>箭给我 我给你斧子 快点 哥们</c>\n\n261\n00:30:28.078 --> 00:30:30.289 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>谢了 哥们</c>\n\n262\n00:30:38.964 --> 00:30:41.884 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>邮件 请让让</c>\n\n263\n00:30:43.010 --> 00:30:44.979 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>给你 非常重要的邮件 信函</c>\n\n264\n00:30:44.979 --> 00:30:46.430 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>这是艘法国船</c>\n\n265\n00:30:46.513 --> 00:30:49.808 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 他说什么？\n- 是要靠岸吗？</c>\n\n266\n00:30:49.889 --> 00:30:53.309 align:middle line:85%,start position:50%,middle\n是的 在南边靠岸\n\n267\n00:30:53.395 --> 00:30:54.949 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>一艘很大的军舰 法国的</c>\n\n268\n00:30:54.949 --> 00:30:57.232 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>10号在这儿泊船 然后向南驶去</c>\n\n269\n00:30:57.309 --> 00:30:59.809 align:middle line:85%,start position:50%,middle\n- 船很大\n- 谢谢 先生\n\n270\n00:31:02.988 --> 00:31:04.823 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>就在这附近</c>\n\n271\n00:31:04.907 --> 00:31:07.492 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>整整领先我们3个礼拜</c>\n\n272\n00:31:07.576 --> 00:31:09.453 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>该死</c>\n\n273\n00:31:10.412 --> 00:31:13.165 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>好了 汤姆 我们立即迎风扬帆吧</c>\n\n274\n00:31:13.248 --> 00:31:17.169 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是 长官 霍勒先生！交易到此为止</c>\n\n275\n00:31:17.252 --> 00:31:19.963 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>伙计们 准备起锚！</c>\n\n276\n00:31:21.965 --> 00:31:24.789 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>放下那个女人 斯莱德！</c>\n\n277\n00:31:24.789 --> 00:31:29.181 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>这是皇家海军军舰 又不是海上妓院</c>\n\n278\n00:31:31.975 --> 00:31:36.063 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>所有船员 装好物品</c>\n\n279\n00:31:48.575 --> 00:31:50.202 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>干的好</c>\n\n280\n00:31:50.285 --> 00:31:52.371 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>先生们…</c>\n\n281\n00:31:53.372 --> 00:31:55.569 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>为妻子和情人们干杯</c>\n\n282\n00:31:55.569 --> 00:31:58.377 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>为妻子和情人们干杯</c>\n\n283\n00:31:58.460 --> 00:32:01.839 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>希望她们不能碰面</c>\n\n284\n00:32:01.922 --> 00:32:05.801 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>霍华德先生 把酒瓶递过来 酒瓶就放你那儿 长官</c>\n\n285\n00:32:06.468 --> 00:32:08.720 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>长官？</c>\n\n286\n00:32:09.638 --> 00:32:11.719 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>抱歉 长官 布莱克尼先生说</c>\n\n287\n00:32:11.719 --> 00:32:14.184 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你曾在尼罗河\n随纳尔逊勋爵作战</c>\n\n288\n00:32:14.268 --> 00:32:19.231 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>的确 那时我是个年轻的上尉 比你现在还小</c>\n\n289\n00:32:19.314 --> 00:32:22.901 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>那时普灵斯先生\n还是个抽泣的见习军官</c>\n\n290\n00:32:22.985 --> 00:32:25.320 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>依然渴望回家去</c>\n\n291\n00:32:25.404 --> 00:32:28.574 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你见过他吗 长官？能告诉我\n他是个什么样的人？</c>\n\n292\n00:32:28.657 --> 00:32:31.785 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我两次有幸与他共进晚餐</c>\n\n293\n00:32:31.869 --> 00:32:34.746 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>每次 他都和我交谈</c>\n\n294\n00:32:34.830 --> 00:32:38.000 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>他是个战术大师 具有独特的眼光</c>\n\n295\n00:32:38.083 --> 00:32:43.338 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>战场上 他总说…“别在意策略 只要冲向他们”</c>\n\n296\n00:32:43.422 --> 00:32:47.593 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>有人会说他不是个好海员 但却是个伟大的领导</c>\n\n297\n00:32:47.676 --> 00:32:50.679 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>如果老波尼入侵英格兰 他是英格兰唯一的希望</c>\n\n298\n00:32:50.762 --> 00:32:54.141 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>长官 我们很想听你讲讲奇闻轶事？</c>\n\n299\n00:32:57.186 --> 00:33:00.272 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>他第一次和我讲话…</c>\n\n300\n00:33:00.355 --> 00:33:05.527 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我永远都忘不了他的话 记忆犹新</c>\n\n301\n00:33:05.611 --> 00:33:09.364 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>他斜靠在桌上 盯着我的眼睛</c>\n\n302\n00:33:09.448 --> 00:33:14.077 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>说：“奥布里…能麻烦你把盐递过来吗？”</c>\n\n303\n00:33:16.163 --> 00:33:21.376 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>自那以后 我总试图模仿他一样说话</c>\n\n304\n00:33:27.132 --> 00:33:32.513 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>第二次…第二次他给我讲了个故事…</c>\n\n305\n00:33:32.596 --> 00:33:36.141 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>在一个寒冷的夜晚 有人如何给了他斗篷</c>\n\n306\n00:33:36.225 --> 00:33:41.146 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>他拒绝了 他不需要 因为他很暖和</c>\n\n307\n00:33:41.230 --> 00:33:45.859 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>他对国王和国家的热心让他觉得温暖</c>\n\n308\n00:33:45.943 --> 00:33:49.988 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我知道另一个人这样说的话 一定很荒谬</c>\n\n309\n00:33:50.072 --> 00:33:53.349 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你们会大喊：“噢 好可怜的家伙” 之后</c>\n\n310\n00:33:53.349 --> 00:33:55.369 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>便仅仅作为一种狂热而忘却</c>\n\n311\n00:33:55.452 --> 00:33:57.579 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>但是 纳尔逊…</c>\n\n312\n00:33:59.414 --> 00:34:02.209 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>能让你感觉到 你的心在发光</c>\n\n313\n00:34:08.590 --> 00:34:11.239 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你不这样认为，普灵斯先生？</c>\n\n314\n00:34:11.239 --> 00:34:13.512 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你说的没错 长官</c>\n\n315\n00:34:14.137 --> 00:34:20.599 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>权力导致腐败这条定律\n在他身上倒成了例外</c>\n\n316\n00:34:20.686 --> 00:34:24.022 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 为纳尔逊勋爵干杯\n- 为纳尔逊勋爵干杯</c>\n\n317\n00:34:24.099 --> 00:34:26.349 align:middle line:85%,start position:50%,middle\n为纳尔逊勋爵干杯\n\n318\n00:34:27.775 --> 00:34:31.196 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你看到那两条象鼻虫了吗 大夫？</c>\n\n319\n00:34:31.280 --> 00:34:32.781 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>看到了</c>\n\n320\n00:34:32.864 --> 00:34:35.199 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你会选择哪一条？</c>\n\n321\n00:34:36.284 --> 00:34:42.119 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>都不会 他们之间没有区别 是同一种象鼻虫</c>\n\n322\n00:34:42.206 --> 00:34:44.626 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>如果你必须选择呢</c>\n\n323\n00:34:44.710 --> 00:34:48.130 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>如果你被迫做个选择呢 如果没有其他…</c>\n\n324\n00:34:48.213 --> 00:34:51.884 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>那么 如果你打算逼迫我…</c>\n\n325\n00:34:54.178 --> 00:34:57.222 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我会选右边的那只</c>\n\n326\n00:34:57.306 --> 00:35:01.018 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>它在长度和宽度上 都有很大的优势</c>\n\n327\n00:35:01.101 --> 00:35:04.438 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你上当了！彻底被骗了</c>\n\n328\n00:35:04.521 --> 00:35:10.402 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>海军生涯总得\n两害相权取其轻</c>\n\n329\n00:35:17.117 --> 00:35:20.537 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>爱玩双关的人\n准是个三只手的小偷</c>\n\n330\n00:35:22.039 --> 00:35:24.291 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>的确！象鼻虫！</c>\n\n331\n00:35:24.374 --> 00:35:26.739 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>为小的那条象鼻虫干杯！</c>\n\n332\n00:35:26.739 --> 00:35:29.671 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>为小的那条象鼻虫干杯！</c>\n\n333\n00:35:40.349 --> 00:35:43.268 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>好啊 乔！</c>\n\n334\n00:35:45.854 --> 00:35:47.940 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>继续 乔！</c>\n\n335\n00:36:06.583 --> 00:36:08.877 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>上帝索取的…</c>\n\n336\n00:36:10.087 --> 00:36:13.006 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>与赋予的都消失了</c>\n\n337\n00:36:13.090 --> 00:36:15.968 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>听见了吗？他说话了！</c>\n\n338\n00:36:16.051 --> 00:36:18.929 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>医生！他说话了 医生！</c>\n\n339\n00:36:19.012 --> 00:36:20.973 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>的确很好 斯蒂芬</c>\n\n340\n00:36:21.056 --> 00:36:24.017 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>再见了 西班牙女郎</c>\n\n341\n00:36:24.101 --> 00:36:28.230 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>永别了 西班牙女郎</c>\n\n342\n00:36:28.313 --> 00:36:33.235 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我们接到命令 要为祖国而远航</c>\n\n343\n00:36:33.318 --> 00:36:39.491 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我们期盼 不久就能重逢</c>\n\n344\n00:36:40.409 --> 00:36:44.538 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>霍伦先生的嗓音真是美妙啊</c>\n\n345\n00:36:44.621 --> 00:36:47.165 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>的确</c>\n\n346\n00:36:48.292 --> 00:36:50.961 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>来吧 初生的牛犊们</c>\n\n347\n00:36:51.044 --> 00:36:53.589 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>听我的劝告吧</c>\n\n348\n00:36:53.672 --> 00:36:58.260 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不要离开你们温暖的家 去与狂暴的大海搏斗</c>\n\n349\n00:37:10.022 --> 00:37:13.150 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>甲板注意！发现帆影！</c>\n\n350\n00:37:14.109 --> 00:37:16.278 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>像是护卫舰！</c>\n\n351\n00:37:20.908 --> 00:37:23.035 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>问题是 它怎么发现我们的？</c>\n\n352\n00:37:23.118 --> 00:37:26.788 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 我们只能掉头应战\n- 敌军又处于上风处</c>\n\n353\n00:37:26.872 --> 00:37:30.125 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>他一定在某个水湾监视我们</c>\n\n354\n00:37:34.129 --> 00:37:37.716 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>天啊 怎么办？他正堵在我们屁股后</c>\n\n355\n00:37:37.799 --> 00:37:39.760 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>像烟雾一样若隐若现</c>\n\n356\n00:37:39.843 --> 00:37:41.869 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我们必须挂上所有风帆</c>\n\n357\n00:37:41.869 --> 00:37:43.764 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>即使用手帕也得干</c>\n\n358\n00:37:43.847 --> 00:37:47.809 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>今天我们一定要挺过去 行动 艾伦先生 先生们</c>\n\n359\n00:37:47.893 --> 00:37:49.937 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>全员 启航！</c>\n\n360\n00:37:50.020 --> 00:37:54.900 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>这是第二次了 决不会再有第三次</c>\n\n361\n00:38:10.832 --> 00:38:16.588 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>告诉你吧 魔鬼掌控着那艘幽灵船</c>\n\n362\n00:38:16.672 --> 00:38:19.049 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你最好抓牢了</c>\n\n363\n00:38:25.347 --> 00:38:27.516 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>这哥们怎么了？</c>\n\n364\n00:38:27.599 --> 00:38:31.189 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>难道我在战场上杀过他的亲属 或许吧？</c>\n\n365\n00:38:31.189 --> 00:38:33.397 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>他的儿子吗？但愿不是</c>\n\n366\n00:38:33.480 --> 00:38:35.482 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>他打仗就和你一样 杰克</c>\n\n367\n00:38:54.126 --> 00:38:57.045 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>把水平仪对准太阳</c>\n\n368\n00:38:57.129 --> 00:39:01.339 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>当下线接触到水平线…\n威尔姆森 看你的六分仪！</c>\n\n369\n00:39:01.425 --> 00:39:05.304 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>太阳不再上升时…</c>\n\n370\n00:39:05.387 --> 00:39:08.974 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>就是到了顶点 也就是正午了</c>\n\n371\n00:39:09.057 --> 00:39:11.476 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 长官？\n- 普灵斯先生</c>\n\n372\n00:39:11.560 --> 00:39:12.929 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>看到已经是正午了 霍伦先生？</c>\n\n373\n00:39:12.929 --> 00:39:13.729 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是 长官</c>\n\n374\n00:39:13.812 --> 00:39:16.315 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>报正午吧，这是你的见习班</c>\n\n375\n00:39:18.609 --> 00:39:21.987 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 长官 正午了\n- 尼科斯先生 到十二点了</c>\n\n376\n00:39:22.070 --> 00:39:24.406 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>还要六小时？</c>\n\n377\n00:39:24.489 --> 00:39:26.742 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>最多五小时</c>\n\n378\n00:39:26.825 --> 00:39:30.787 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>午夜前 我们别进入她的射程</c>\n\n379\n00:39:38.921 --> 00:39:42.299 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>它得看起来像咱们的船，伙计们，别忘了</c>\n\n380\n00:39:42.299 --> 00:39:43.842 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>吉波 系牢那些缆绳</c>\n\n381\n00:39:43.926 --> 00:39:47.387 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>由于风的原因 别再升高了</c>\n\n382\n00:39:47.471 --> 00:39:50.729 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>抱歉 长官 他们在捆什么？</c>\n\n383\n00:39:50.729 --> 00:39:53.549 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>这是你指挥的第一艘舰</c>\n\n384\n00:39:59.483 --> 00:40:01.860 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>快点 她就要追上我们了</c>\n\n385\n00:40:01.944 --> 00:40:04.863 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>把份量都压在索具上</c>\n\n386\n00:40:04.947 --> 00:40:07.199 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>挡开 挡开</c>\n\n387\n00:40:07.282 --> 00:40:09.826 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>放下小艇</c>\n\n388\n00:40:16.792 --> 00:40:19.962 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 我们不希望你牺牲\n- 是 长官</c>\n\n389\n00:40:31.056 --> 00:40:36.603 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>有根船索 在船尾送他下去 一切都得小心</c>\n\n390\n00:40:36.687 --> 00:40:40.983 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>现在好了 要10分钟才能追上我们</c>\n\n391\n00:40:46.989 --> 00:40:48.839 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>记住船长对你说的话</c>\n\n392\n00:40:48.839 --> 00:40:50.951 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>用力拉 伙计们 对</c>\n\n393\n00:41:14.558 --> 00:41:15.559 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>好了</c>\n\n394\n00:41:21.273 --> 00:41:24.151 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>奇利克！熄灯！</c>\n\n395\n00:41:30.616 --> 00:41:32.201 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>艾伦先生 准备</c>\n\n396\n00:42:13.408 --> 00:42:15.827 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>嗨 我们抓到鱼了</c>\n\n397\n00:42:17.412 --> 00:42:19.331 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>掌舵 邦登</c>\n\n398\n00:42:19.414 --> 00:42:23.126 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 快 别给我讲这很没意思\n- 是 长官</c>\n\n399\n00:42:24.920 --> 00:42:27.548 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>左满舵！</c>\n\n400\n00:42:56.493 --> 00:43:01.039 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>让弟兄们解散，普灵斯先生，我来当值</c>\n\n401\n00:43:01.123 --> 00:43:02.708 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是 长官</c>\n\n402\n00:43:02.791 --> 00:43:07.379 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>莫威先生 艾伦先生 冷静下来 你们知道命令的</c>\n\n403\n00:43:07.462 --> 00:43:09.548 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>干得好 长官</c>\n\n404\n00:43:11.341 --> 00:43:15.929 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>真是幽灵 确实 再次出现又恰恰是在我们后面</c>\n\n405\n00:43:16.013 --> 00:43:21.393 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>神不知鬼不觉 又在我们后面\n和上次雾里出现一样</c>\n\n406\n00:43:21.476 --> 00:43:23.937 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我们的炮打不到她</c>\n\n407\n00:43:24.021 --> 00:43:26.982 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>要是没有原因 船长就不会叫“幸运杰克”了</c>\n\n408\n00:43:27.065 --> 00:43:31.153 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不管是不是幽灵 只是艘掠私舰 船长会战胜她的</c>\n\n409\n00:43:31.236 --> 00:43:34.114 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>对付幽灵 光靠运气就不够了</c>\n\n410\n00:43:35.991 --> 00:43:39.161 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 就像海盗船吗？\n- 不 不是海盗 阁下</c>\n\n411\n00:43:39.244 --> 00:43:43.832 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>噢 不 如果是海盗的话 看到后 就能绞死他们了</c>\n\n412\n00:43:43.916 --> 00:43:46.752 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>私掠舰从法国人那里得到命令</c>\n\n413\n00:43:46.835 --> 00:43:49.463 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>能够截获任何一艘英国船只</c>\n\n414\n00:43:49.546 --> 00:43:53.258 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>他们攻击满载的商船之类的</c>\n\n415\n00:43:53.342 --> 00:43:57.095 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>嘿 想象一下我们的战利品吧</c>\n\n416\n00:43:57.179 --> 00:44:02.142 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>满载的黄金 还有龙涎香和阿拉伯珠宝</c>\n\n417\n00:44:02.226 --> 00:44:05.771 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>那真是太好了 纳格 回家有钱花了 但</c>\n\n418\n00:44:05.854 --> 00:44:08.106 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>但决不要死人请我喝酒</c>\n\n419\n00:44:08.190 --> 00:44:12.152 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你也没有请过活人喝酒</c>\n\n420\n00:44:13.570 --> 00:44:19.701 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>彻夜未眠 都冰凉了 这也是最后一杯咖啡了</c>\n\n421\n00:44:19.785 --> 00:44:21.870 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>谢谢你，奇利克</c>\n\n422\n00:44:26.208 --> 00:44:28.252 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>邦登</c>\n\n423\n00:44:28.335 --> 00:44:31.505 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>向东航行差不多了 现在像西南偏南方向行驶</c>\n\n424\n00:44:31.588 --> 00:44:35.592 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是 长官 西南偏南</c>\n\n425\n00:44:39.638 --> 00:44:42.140 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>发现帆影！</c>\n\n426\n00:44:42.224 --> 00:44:45.352 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>右前方两个罗经点方向！</c>\n\n427\n00:44:45.936 --> 00:44:48.397 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>为“幸运杰克”欢呼三声！</c>\n\n428\n00:44:48.469 --> 00:44:53.349 align:middle line:85%,start position:50%,middle\n万岁！万岁！万岁！\n\n429\n00:44:54.570 --> 00:44:56.905 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>此战必胜 伙计们！</c>\n\n430\n00:45:06.665 --> 00:45:10.836 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>犯规了！你抢先了</c>\n\n431\n00:45:15.007 --> 00:45:18.010 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 挂上皇家帆和下桁主帆！\n- 遵命，长官</c>\n\n432\n00:45:18.093 --> 00:45:20.554 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>让不值班的人都站到舷墙边去</c>\n\n433\n00:45:20.637 --> 00:45:22.598 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>从没见过这样的</c>\n\n434\n00:45:22.681 --> 00:45:26.685 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>本来落后100多海里的 现在却尾随其后</c>\n\n435\n00:45:26.768 --> 00:45:30.898 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>这就是航海术，普灵斯，天哪，这就是航海术</c>\n\n436\n00:45:30.981 --> 00:45:34.359 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我告诉过你这有作用的\n威尔 黄昏前就能击退他们</c>\n\n437\n00:45:34.443 --> 00:45:35.949 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我想我们追上了 长官</c>\n\n438\n00:45:35.949 --> 00:45:37.905 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>这次的风向对我们有利</c>\n\n439\n00:45:37.988 --> 00:45:41.283 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>别高兴得太早</c>\n\n440\n00:45:41.366 --> 00:45:46.288 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>如果我们能靠近尾随的话 就胜利在握了</c>\n\n441\n00:45:46.371 --> 00:45:48.707 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>大家做好迎战准备</c>\n\n442\n00:45:49.374 --> 00:45:52.920 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>转三圈 愿主保佑我们</c>\n\n443\n00:46:08.477 --> 00:46:10.145 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>转！</c>\n\n444\n00:46:10.229 --> 00:46:14.024 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>前进 伙计 否则炮还没上膛就赢了</c>\n\n445\n00:46:14.107 --> 00:46:16.235 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>坚持住！</c>\n\n446\n00:46:17.069 --> 00:46:20.656 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 12节 长官\n- 是12节 很好</c>\n\n447\n00:46:20.739 --> 00:46:25.410 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>还要更快！让闲散人员\n都站到上风舷去！</c>\n\n448\n00:46:25.494 --> 00:46:28.830 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>霍勒先生 叫醒换班的人</c>\n\n449\n00:46:29.748 --> 00:46:33.043 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>大家右舷集合！</c>\n\n450\n00:46:33.752 --> 00:46:37.172 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>松开左舷中桅帆角索！</c>\n\n451\n00:46:54.773 --> 00:46:56.089 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我们在疾驶！</c>\n\n452\n00:46:56.089 --> 00:46:59.278 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>他再不收敛点\n我们马上就要折断桅杆了！</c>\n\n453\n00:46:59.361 --> 00:47:03.949 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>船长了解这船 他知道有多大承受力</c>\n\n454\n00:47:07.279 --> 00:47:09.159 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 啊！\n- 霍勒先生！</c>\n\n455\n00:47:09.239 --> 00:47:12.541 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>霍勒先生 把救生索绕到船头和船尾！</c>\n\n456\n00:47:12.624 --> 00:47:14.334 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>别闲着 伙计！</c>\n\n457\n00:47:14.418 --> 00:47:20.090 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>首尾拉好救生索！\n把大艇双重捆牢！</c>\n\n458\n00:47:22.384 --> 00:47:24.761 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>合恩角 医生</c>\n\n459\n00:47:40.569 --> 00:47:43.572 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>盖上盖子 酒里面水分已经够多了</c>\n\n460\n00:47:43.655 --> 00:47:45.532 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>谢谢你了 戴维斯</c>\n\n461\n00:47:45.616 --> 00:47:50.495 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>船长会跟着她 绕着合恩角全速航行吗？</c>\n\n462\n00:47:50.579 --> 00:47:52.998 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我看船长会跟着她到天涯海角</c>\n\n463\n00:47:53.081 --> 00:47:57.628 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>这是艘恶魔的船只 我告诉你 我们正在误入陷阱</c>\n\n464\n00:48:01.089 --> 00:48:03.926 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>敌军正绕着合恩角转圈 长官</c>\n\n465\n00:48:04.009 --> 00:48:06.970 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我不敢确信这是阴谋 别绕着合恩角转圈了</c>\n\n466\n00:48:07.054 --> 00:48:10.057 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>谢谢 你的话会被记录到航海日志中</c>\n\n467\n00:48:10.140 --> 00:48:16.438 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>水手们各就位！收帆 伙计们 帆张得太开了</c>\n\n468\n00:48:16.522 --> 00:48:18.649 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>拉住 绳子系上！</c>\n\n469\n00:48:34.164 --> 00:48:37.709 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我们离她很近了 汤姆 这次我不会放弃了</c>\n\n470\n00:48:37.793 --> 00:48:41.046 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>迎风而上 巴瑞特 航向西南偏西</c>\n\n471\n00:48:41.129 --> 00:48:43.715 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>西南偏西 长官</c>\n\n472\n00:48:44.883 --> 00:48:46.593 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>卡拉米先生</c>\n\n473\n00:48:46.677 --> 00:48:49.388 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>闲杂人等都到下边去</c>\n\n474\n00:48:53.183 --> 00:48:55.936 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我们正驶往合恩角 伙计们！</c>\n\n475\n00:48:59.982 --> 00:49:01.859 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>收好上桅帆！</c>\n\n476\n00:49:15.414 --> 00:49:17.124 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>精神点 伙计们！</c>\n\n477\n00:49:21.461 --> 00:49:26.216 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>赶在下沉前封住缺口！</c>\n\n478\n00:49:35.684 --> 00:49:38.604 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>弗朗西斯、特鲁洛夫\n去后桅！</c>\n\n479\n00:49:40.063 --> 00:49:41.940 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>安全了</c>\n\n480\n00:49:42.024 --> 00:49:44.026 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>去下面 伙计们</c>\n\n481\n00:49:50.532 --> 00:49:55.162 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>霍伦先生 帮帮后桅上桅帆的小威利</c>\n\n482\n00:49:58.665 --> 00:50:02.002 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 我还需要人手 长官\n- 好的 快去</c>\n\n483\n00:50:10.385 --> 00:50:14.056 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>霍伦先生 长官！救救我！</c>\n\n484\n00:50:20.896 --> 00:50:24.566 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>都铎 埃拉斯！到艾伦先生那儿去！</c>\n\n485\n00:50:24.650 --> 00:50:29.613 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你们几个登桅！去后桅上桅帆！\n把缆绳顺过去！</c>\n\n486\n00:50:37.579 --> 00:50:39.665 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>救命啊！</c>\n\n487\n00:50:42.751 --> 00:50:44.753 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>救救我！</c>\n\n488\n00:50:50.551 --> 00:50:53.428 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>有人掉下海了！</c>\n\n489\n00:50:54.555 --> 00:50:59.017 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>后桅完了！船尾栏杆需要人手！</c>\n\n490\n00:51:10.153 --> 00:51:13.031 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>他在那儿 长官！</c>\n\n491\n00:51:13.115 --> 00:51:16.743 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>快游过来 伙计！朝救生筏游 伙计！</c>\n\n492\n00:51:17.619 --> 00:51:19.288 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>过来！</c>\n\n493\n00:51:19.371 --> 00:51:24.710 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>艾伦先生 栏杆 木桶 能浮起来的东西都扔出去</c>\n\n494\n00:51:24.793 --> 00:51:28.881 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>船身横过来了！\n我们要失控了！</c>\n\n495\n00:51:28.964 --> 00:51:32.301 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>长官，落水残骸\n成了拖曳海锚！</c>\n\n496\n00:51:32.384 --> 00:51:35.929 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我们必须切开！否则我们都会沉没！</c>\n\n497\n00:51:36.013 --> 00:51:39.892 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>长官 他快要到了！他能行！</c>\n\n498\n00:51:39.975 --> 00:51:43.979 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 快游啊 威尔！\n- 快游啊 继续游啊！</c>\n\n499\n00:51:44.062 --> 00:51:49.234 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>上帝保佑 威尔 游啊！朝救生筏游 威尔！</c>\n\n500\n00:51:57.868 --> 00:51:59.786 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你能行的 威尔！</c>\n\n501\n00:51:59.870 --> 00:52:03.999 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 快游！快啊！\n- 快游啊 威尔！游啊！</c>\n\n502\n00:54:33.690 --> 00:54:37.110 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 又来了\n- 谁又来了？</c>\n\n503\n00:54:37.194 --> 00:54:40.030 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 约拿\n- 什么？</c>\n\n504\n00:54:50.415 --> 00:54:54.878 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>战死的还能忍受</c>\n\n505\n00:54:55.712 --> 00:55:02.636 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>对我而言 手术刀下死的\n或是并发症感染而亡的…</c>\n\n506\n00:55:02.719 --> 00:55:08.684 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我不得不安慰自己\n是敌人让他们牺牲的 而不是我</c>\n\n507\n00:55:10.853 --> 00:55:13.397 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>那个年轻人是战死的</c>\n\n508\n00:55:16.191 --> 00:55:20.445 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>就如你说 只能两害相权取其轻</c>\n\n509\n00:55:20.529 --> 00:55:22.573 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>象鼻虫</c>\n\n510\n00:55:26.034 --> 00:55:30.455 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>可这对船员士气打击很大 威利很受欢迎</c>\n\n511\n00:55:30.539 --> 00:55:34.543 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>他们有没有对你表示失望？</c>\n\n512\n00:55:41.884 --> 00:55:44.887 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>杰克 在回答之前 我得问你</c>\n\n513\n00:55:44.970 --> 00:55:49.057 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我是在和老朋友 还是在和船长讲话？</c>\n\n514\n00:55:50.225 --> 00:55:53.812 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>如果是船长的话 我会说我最痛恨告密者了</c>\n\n515\n00:55:53.896 --> 00:55:55.578 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你就像爱尔兰人讲话一样</c>\n\n516\n00:55:55.578 --> 00:55:57.149 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我就是爱尔兰人</c>\n\n517\n00:55:57.232 --> 00:55:59.318 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>呃 那作为朋友呢</c>\n\n518\n00:55:59.401 --> 00:56:05.199 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>作为朋友 我会说 我从没怀疑过你的指挥能力</c>\n\n519\n00:56:05.282 --> 00:56:07.159 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>坦白的讲 斯蒂芬</c>\n\n520\n00:56:08.994 --> 00:56:13.707 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>也许我们早该在几个礼拜前 就应该掉头</c>\n\n521\n00:56:13.790 --> 00:56:17.669 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>船员们…当然他们会跟“\n幸运杰克”到天涯海角</c>\n\n522\n00:56:17.753 --> 00:56:20.005 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>对胜利充满信心</c>\n\n523\n00:56:20.088 --> 00:56:25.761 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>但是 有一个问题 你从未失败过</c>\n\n524\n00:56:27.262 --> 00:56:33.468 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>追逐一艘又大又快\n枪坚炮利的敌舰 似乎妄自尊大</c>\n\n525\n00:56:33.560 --> 00:56:36.980 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>这不是妄自尊大 这是责无旁贷</c>\n\n526\n00:56:37.064 --> 00:56:39.525 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>责任 是的 我听得够多了</c>\n\n527\n00:56:39.608 --> 00:56:44.238 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>就像你挖苦我说 用显微镜看世界是你的特权</c>\n\n528\n00:56:44.321 --> 00:56:48.825 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>这是艘战舰 我会不惜一切完成任务</c>\n\n529\n00:56:48.909 --> 00:56:51.370 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不惜一切？</c>\n\n530\n00:56:51.453 --> 00:56:53.705 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不惜一切</c>\n\n531\n00:56:53.789 --> 00:56:56.542 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>服从命令 不惜一切</c>\n\n532\n00:56:56.625 --> 00:57:00.921 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你能声称 执行命令就无视任何私人情感吗？</c>\n\n533\n00:57:01.004 --> 00:57:03.549 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>服从命令是军人的天职</c>\n\n534\n00:57:03.632 --> 00:57:09.878 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我的任务是 尾随敌舰直到巴西 不过已做过头了</c>\n\n535\n00:57:12.140 --> 00:57:14.184 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>抓住了</c>\n\n536\n00:57:17.729 --> 00:57:20.732 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>风又转向了 长官</c>\n\n537\n00:57:20.816 --> 00:57:24.820 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>长官 我们不能再向西行驶了</c>\n\n538\n00:57:25.487 --> 00:57:31.488 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>如果不能乘风破浪 汤姆 那就只能绕路了 正南</c>\n\n539\n00:57:31.577 --> 00:57:34.580 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>向南航行多远 长官？</c>\n\n540\n00:57:34.663 --> 00:57:38.250 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>该航行多远就多远，普灵斯</c>\n\n541\n00:57:38.333 --> 00:57:40.752 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 是 长官\n- 精神点！</c>\n\n542\n00:57:41.837 --> 00:57:46.008 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 航线正南 拜托 邦登\n- 正南 长官</c>\n\n543\n00:57:48.552 --> 00:57:51.680 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>用力举！稳住！</c>\n\n544\n00:58:20.828 --> 00:58:22.208 align:middle line:85%,start position:50%,middle\n啊…\n\n545\n00:58:22.788 --> 00:58:25.498 align:middle line:85%,start position:50%,middle\n万岁！\n\n546\n00:58:27.007 --> 00:58:31.345 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>很明显很有趣 但我很疑惑</c>\n\n547\n00:58:31.428 --> 00:58:35.974 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我们正掉头向北\n迎着太阳驶去</c>\n\n548\n00:58:36.058 --> 00:58:38.060 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 为太阳干杯\n- 为太阳干杯！</c>\n\n549\n00:58:40.729 --> 00:58:44.358 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>噢 我知道会这样</c>\n\n550\n00:58:44.441 --> 00:58:50.072 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>所以我让奇利克\n准备了些特别的东西</c>\n\n551\n00:58:50.155 --> 00:58:51.988 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>奇利克！奇利克！</c>\n\n552\n00:58:51.988 --> 00:58:54.451 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我早就在这儿 不是吗？</c>\n\n553\n00:58:56.954 --> 00:59:01.124 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>先生们 给你们看…</c>\n\n554\n00:59:01.959 --> 00:59:04.253 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我们的目的地</c>\n\n555\n00:59:10.592 --> 00:59:12.348 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>这是加拉帕哥斯群岛！</c>\n\n556\n00:59:12.348 --> 00:59:14.263 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>加拉帕哥斯群岛！</c>\n\n557\n00:59:16.932 --> 00:59:19.184 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我们的捕鲸舰队就在那儿</c>\n\n558\n00:59:19.268 --> 00:59:24.731 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>他们的货物会很值钱</c>\n\n559\n00:59:24.815 --> 00:59:30.529 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>“地狱神”号一定会去那儿 我肯定</c>\n\n560\n00:59:30.612 --> 00:59:33.282 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>普灵斯先生，如果你允许的话…</c>\n\n561\n00:59:33.365 --> 00:59:36.326 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>给你切一块阿尔伯马尔岛</c>\n\n562\n00:59:37.327 --> 00:59:40.956 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>这是给你的 医生 雷东多暗礁</c>\n\n563\n00:59:41.039 --> 00:59:42.374 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>太好了</c>\n\n564\n00:59:42.457 --> 00:59:45.210 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>“地狱神”号 归我</c>\n\n565\n00:59:51.383 --> 00:59:56.638 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>平安回家 让海水尽情咆哮吧</c>\n\n566\n00:59:56.722 --> 01:00:01.727 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>平安回家 让海水尽情咆哮吧</c>\n\n567\n01:00:01.810 --> 01:00:08.066 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>辗转反侧 凯旋而归</c>\n\n568\n01:00:08.150 --> 01:00:13.447 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>勿忘战友…</c>\n\n569\n01:00:13.530 --> 01:00:18.952 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我们曾经共事甲板</c>\n\n570\n01:00:19.036 --> 01:00:24.750 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我洗炮身 你填弹</c>\n\n571\n01:00:24.833 --> 01:00:31.173 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>辗转反侧 凯旋而归</c>\n\n572\n01:00:31.256 --> 01:00:38.508 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>勿忘战友…</c>\n\n573\n01:01:19.968 --> 01:01:22.718 align:middle line:85%,start position:50%,middle\n加拉帕戈斯群岛\n\n574\n01:01:22.808 --> 01:01:29.606 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>迷幻群岛 据说岛上都是珍禽异兽</c>\n\n575\n01:01:30.482 --> 01:01:33.569 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>到那儿后 我们要停下来补充水和食物</c>\n\n576\n01:01:33.652 --> 01:01:37.656 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我保证 这期间…至少需要停靠三天…</c>\n\n577\n01:01:37.739 --> 01:01:42.160 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你可以随意采撷想要的珍稀物种</c>\n\n578\n01:01:42.244 --> 01:01:46.707 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你可能是第一个登上此岛的博物学家 我打赌</c>\n\n579\n01:01:46.790 --> 01:01:50.169 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>呃 我会上面喜欢所有的东西</c>\n\n580\n01:01:53.797 --> 01:01:57.009 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 这昆虫吗？\n- 是的</c>\n\n581\n01:01:58.927 --> 01:02:03.765 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>看上去不像 我是说 像树枝</c>\n\n582\n01:02:04.516 --> 01:02:06.894 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是的 说到点子上了</c>\n\n583\n01:02:06.977 --> 01:02:10.898 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>为了生存伪装自己</c>\n\n584\n01:02:14.943 --> 01:02:19.615 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>瞧 这是只蜘蛛 伪装成蚂蚁</c>\n\n585\n01:02:19.698 --> 01:02:26.988 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>还有伪装成荆棘花的昆虫 这样才不会被鸟吃掉</c>\n\n586\n01:02:28.498 --> 01:02:30.709 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>上帝给了他们这种能力吗？</c>\n\n587\n01:02:30.792 --> 01:02:34.213 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>上帝给了他们这种能力？当然</c>\n\n588\n01:02:34.296 --> 01:02:37.716 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>但是他们自己会伪装吗？</c>\n\n589\n01:02:37.799 --> 01:02:40.677 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>这还是个问题 对吧？</c>\n\n590\n01:02:42.679 --> 01:02:45.390 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>长官！我们看到\n加拉帕戈斯群岛了！</c>\n\n591\n01:02:45.474 --> 01:02:47.518 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>来了！</c>\n\n592\n01:03:22.386 --> 01:03:26.181 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 看 岩石后面\n- 噢 是的 看见了</c>\n\n593\n01:03:26.265 --> 01:03:29.935 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是什么？令人费解 呃？一种海鸟？</c>\n\n594\n01:03:30.018 --> 01:03:32.838 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>那儿还有一只奇丑无比的魔鬼</c>\n\n595\n01:03:32.838 --> 01:03:35.482 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>真恶心！满身是疙瘩</c>\n\n596\n01:03:35.566 --> 01:03:38.443 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>奇丑无比 对吧？</c>\n\n597\n01:03:39.528 --> 01:03:42.155 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>没见到女人 只有鸭子和蜥蜴</c>\n\n598\n01:03:42.239 --> 01:03:45.117 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>什么 没女人？不正常</c>\n\n599\n01:03:46.535 --> 01:03:48.370 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>真是太特别了</c>\n\n600\n01:03:48.453 --> 01:03:50.289 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>什么 长官？</c>\n\n601\n01:03:50.372 --> 01:03:54.459 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>那些鸟 一种鸬鹚 但是不能飞</c>\n\n602\n01:03:54.543 --> 01:03:57.129 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>看见它们退化的翅膀吗？</c>\n\n603\n01:03:57.212 --> 01:04:00.841 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>天哪 可能还是未知的物种呢</c>\n\n604\n01:04:00.924 --> 01:04:04.678 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>那龙看起来并不想打搅它们？</c>\n\n605\n01:04:05.387 --> 01:04:09.808 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不 我想那是一种鬣蜥 因此 是食草类动物</c>\n\n606\n01:04:09.892 --> 01:04:12.978 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 能抓一只吗？\n- 我想 要抓就抓一对</c>\n\n607\n01:04:13.061 --> 01:04:16.273 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>然后你就能把后代献给国王</c>\n\n608\n01:04:16.356 --> 01:04:20.027 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 看 有一只要下水了\n- 鬣蜥不会游泳</c>\n\n609\n01:04:20.110 --> 01:04:22.404 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>这些会</c>\n\n610\n01:04:31.455 --> 01:04:33.582 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>呃 见鬼</c>\n\n611\n01:04:33.665 --> 01:04:40.005 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>几分钟就出现了两个新物种 真是难以置信</c>\n\n612\n01:05:03.320 --> 01:05:08.242 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>全体船员！离开船舷！准备拉动主桅！</c>\n\n613\n01:05:17.543 --> 01:05:21.129 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 奥布里\n- 霍格，“信天翁”号船长</c>\n\n614\n01:05:21.213 --> 01:05:24.675 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>上帝保佑你 船长 上帝保佑所有人</c>\n\n615\n01:05:25.676 --> 01:05:27.608 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>卡拉米先生 给这些人的食物和水</c>\n\n616\n01:05:27.608 --> 01:05:28.637 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是 长官</c>\n\n617\n01:05:28.720 --> 01:05:30.448 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>霍华德先生 让你的人下去</c>\n\n618\n01:05:30.448 --> 01:05:32.140 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>皇家海军陆战队，平端枪！</c>\n\n619\n01:05:33.058 --> 01:05:36.103 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不到一周前 我们回来开辟新航线</c>\n\n620\n01:05:36.186 --> 01:05:41.650 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>藏在那边水湾的人\n烧了我们所有的船 妈的海盗！</c>\n\n621\n01:05:41.733 --> 01:05:43.986 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>船员被囚禁 船长死了</c>\n\n622\n01:05:44.069 --> 01:05:48.240 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是艘很大的三桅船 很可怕</c>\n\n623\n01:05:48.323 --> 01:05:51.668 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>他们偷走了价值12000英镑的上等油</c>\n\n624\n01:05:51.668 --> 01:05:53.579 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我们流亡了至少两年</c>\n\n625\n01:05:53.662 --> 01:05:55.581 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>海盗船开去哪儿了？</c>\n\n626\n01:05:55.664 --> 01:05:58.750 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>或许往西南去与同伙会师了</c>\n\n627\n01:05:58.834 --> 01:06:02.045 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>普灵斯先生，把这些人的名字登记入册</c>\n\n628\n01:06:02.129 --> 01:06:05.424 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>艾伦 调整航向 西南方</c>\n\n629\n01:06:05.507 --> 01:06:07.759 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>全体船员 启航！</c>\n\n630\n01:06:07.843 --> 01:06:10.846 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>长官 我们要更新些补给品的？</c>\n\n631\n01:06:10.929 --> 01:06:14.057 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>莫威先生 不能再浪费时间了</c>\n\n632\n01:06:29.188 --> 01:06:34.286 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 杰克 你忘了自己的许诺？\n- 服从军纪</c>\n\n633\n01:06:34.369 --> 01:06:37.539 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我不能由于鬣蜥和野猪而造成拖延</c>\n\n634\n01:06:37.623 --> 01:06:41.126 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>的确很吸引人 但也不用着急</c>\n\n635\n01:06:41.210 --> 01:06:45.214 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我想有个办法能达成两方的夙愿</c>\n\n636\n01:06:45.297 --> 01:06:48.467 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我知道 这是个狭长的岛屿</c>\n\n637\n01:06:48.550 --> 01:06:52.054 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你需要绕着岛行驶 我可以穿越过去</c>\n\n638\n01:06:52.137 --> 01:06:56.058 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我知道你会花数小时研究一个遗弃的鸟窝</c>\n\n639\n01:06:56.141 --> 01:07:00.145 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我能够很快地穿过去 只在必要的时候停留片刻</c>\n\n640\n01:07:00.229 --> 01:07:04.358 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>新的发现可以更新自然史</c>\n\n641\n01:07:04.441 --> 01:07:08.529 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>如果是逆风逆流而行的话 我会让你去</c>\n\n642\n01:07:08.612 --> 01:07:11.823 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>但不是 我必须说不行</c>\n\n643\n01:07:13.492 --> 01:07:17.204 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我终于明白了 这么久以来我服侍你的左右</c>\n\n644\n01:07:17.287 --> 01:07:22.167 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我唯一得到满足的只是作为你的一部战争机器</c>\n\n645\n01:07:22.251 --> 01:07:25.038 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>对大自然的神奇视而不见 一心只想着战斗</c>\n\n646\n01:07:25.038 --> 01:07:27.256 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我并不是说你权力欲膨胀…</c>\n\n647\n01:07:27.339 --> 01:07:29.128 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你忘记了你的身份 医生</c>\n\n648\n01:07:29.128 --> 01:07:30.926 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我没有忘记 杰克</c>\n\n649\n01:07:31.009 --> 01:07:35.347 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不，杰克，是你失态了\n承诺就必须遵守</c>\n\n650\n01:07:35.430 --> 01:07:36.468 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我也是身不由己</c>\n\n651\n01:07:36.468 --> 01:07:39.726 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我指挥的是国王的战舰\n不是私人游艇！</c>\n\n652\n01:07:39.810 --> 01:07:43.897 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我们没时间来满足你的个人嗜好 先生！</c>\n\n653\n01:08:11.884 --> 01:08:14.303 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>好 好！</c>\n\n654\n01:08:16.305 --> 01:08:21.894 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>把鱼都拿下去 把甲板清洗干净</c>\n\n655\n01:08:21.977 --> 01:08:25.229 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>戴维斯 别落下什么 统统拿下去</c>\n\n656\n01:08:25.314 --> 01:08:26.982 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>布莱克尼</c>\n\n657\n01:08:27.064 --> 01:08:31.236 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>长官 我在甲板上发现一只活着的甲壳虫</c>\n\n658\n01:08:34.488 --> 01:08:37.326 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我猜这是龟岛的某种甲壳虫</c>\n\n659\n01:08:38.368 --> 01:08:40.078 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>应该是的</c>\n\n660\n01:08:41.330 --> 01:08:43.598 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>即使你花上一整天搜索全岛</c>\n\n661\n01:08:43.598 --> 01:08:46.502 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>说不定也找不到这样一只甲壳虫</c>\n\n662\n01:08:48.670 --> 01:08:51.965 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>对</c>\n\n663\n01:08:52.758 --> 01:08:55.176 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>送给你</c>\n\n664\n01:09:11.568 --> 01:09:14.112 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>布莱克尼</c>\n\n665\n01:09:15.363 --> 01:09:18.450 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 谢谢\n- 长官</c>\n\n666\n01:09:31.880 --> 01:09:33.841 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>炮弹放完了 长官</c>\n\n667\n01:09:33.924 --> 01:09:37.553 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 用时多少？\n- 2分零1秒 长官</c>\n\n668\n01:09:37.636 --> 01:09:42.975 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>伙计们 还要努力 我们要两面开炮 夹攻对手</c>\n\n669\n01:09:43.058 --> 01:09:45.238 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>想在皮卡蒂里大街看砍头示众吗？</c>\n\n670\n01:09:45.238 --> 01:09:46.310 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不想！</c>\n\n671\n01:09:46.395 --> 01:09:49.564 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 想称拿破仑为陛下吗？\n- 不想！</c>\n\n672\n01:09:49.648 --> 01:09:52.401 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 想让后代都唱马赛曲吗？\n- 不要！</c>\n\n673\n01:09:52.484 --> 01:09:55.737 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>莫威、普灵斯，右舷炮组重新装填！</c>\n\n674\n01:09:58.782 --> 01:10:02.077 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>快 掌握节奏！</c>\n\n675\n01:10:04.746 --> 01:10:08.083 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 瞄准目标！\n- 伙计们 加油啊！</c>\n\n676\n01:10:08.166 --> 01:10:10.210 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>加油！</c>\n\n677\n01:10:22.097 --> 01:10:24.474 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>用力啦啊！</c>\n\n678\n01:10:24.558 --> 01:10:25.958 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>报告，莫威先生</c>\n\n679\n01:10:25.968 --> 01:10:27.769 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>第三第四组准备好了</c>\n\n680\n01:10:27.853 --> 01:10:30.689 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>好 右舷 开火！</c>\n\n681\n01:11:04.598 --> 01:11:06.767 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>1分10秒！</c>\n\n682\n01:11:06.888 --> 01:11:08.548 align:middle line:85%,start position:50%,middle\n太棒了！\n\n683\n01:11:08.644 --> 01:11:11.313 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>干得好，小伙子们！\n给你们的奖励是这些好的酒</c>\n\n684\n01:11:11.388 --> 01:11:13.518 align:middle line:85%,start position:50%,middle\n好啊！\n\n685\n01:11:15.484 --> 01:11:17.903 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>给船长让路 小伙子们</c>\n\n686\n01:11:17.986 --> 01:11:20.656 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>进步很显著 卡拉米先生，干得好！</c>\n\n687\n01:11:20.739 --> 01:11:22.824 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>谢谢，长官！</c>\n\n688\n01:11:29.206 --> 01:11:34.628 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>奇利克！奇利克！今天吃什么？</c>\n\n689\n01:11:34.711 --> 01:11:37.256 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 腌猪头肉\n- 什么？</c>\n\n690\n01:11:37.339 --> 01:11:42.010 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 腌猪头肉！\n- 我最喜欢的，最最喜欢的！</c>\n\n691\n01:11:42.094 --> 01:11:48.725 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>等他们逃跑时出其不意！\n把她轰上西天！</c>\n\n692\n01:12:45.073 --> 01:12:46.278 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>再这样下去一个星期</c>\n\n693\n01:12:46.278 --> 01:12:48.452 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我情愿拿这一切\n换一杯清水</c>\n\n694\n01:12:48.535 --> 01:12:50.662 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我能利用风做航行动力</c>\n\n695\n01:12:52.581 --> 01:12:56.168 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>却不能唤雨，我他妈又不是上帝</c>\n\n696\n01:12:56.251 --> 01:12:58.837 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我没想到运气会这么差</c>\n\n697\n01:13:15.270 --> 01:13:21.109 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>“他们对他说 '厄运为何降临？”'</c>\n\n698\n01:13:24.988 --> 01:13:27.282 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>哪儿学来的？</c>\n\n699\n01:13:28.283 --> 01:13:33.205 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>圣经上的，《约拿书》</c>\n\n700\n01:13:33.288 --> 01:13:37.125 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>他们发现同船有个\n叫约拿的家伙</c>\n\n701\n01:13:37.209 --> 01:13:40.212 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>他冒犯了上帝，所以才招致厄运</c>\n\n702\n01:13:40.295 --> 01:13:45.968 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>厄运如降临 他就是厄运之源</c>\n\n703\n01:13:46.051 --> 01:13:50.806 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>哦 哦 看来乔知道些关于厄运的事情</c>\n\n704\n01:13:51.640 --> 01:13:55.310 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是你的亲身体验，是吗 乔？</c>\n\n705\n01:14:07.030 --> 01:14:09.418 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>正如奇利克说的 早上战斗的时候</c>\n\n706\n01:14:09.418 --> 01:14:12.452 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>他连召唤船员进入战斗岗位的勇气都没有</c>\n\n707\n01:14:12.536 --> 01:14:14.748 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>他的整个炮手班都死光了</c>\n\n708\n01:14:14.748 --> 01:14:17.165 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>他一到后桅 威尔就倒下了</c>\n\n709\n01:14:17.249 --> 01:14:21.044 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>风停的时候 大家想想是谁在值班？</c>\n\n710\n01:14:43.400 --> 01:14:46.028 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你，站住！</c>\n\n711\n01:14:48.155 --> 01:14:52.326 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>纠察长 把这家伙带下去锁起来！</c>\n\n712\n01:14:52.409 --> 01:14:55.954 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>普灵斯先生，违纪者打八响钟时受罚</c>\n\n713\n01:14:56.038 --> 01:14:57.748 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是的，长官！</c>\n\n714\n01:14:59.208 --> 01:15:02.461 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>叫霍伦到我的船舱里来！</c>\n\n715\n01:15:06.507 --> 01:15:09.760 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>那个人撞了你 你却什么都没说 我想知道为什么</c>\n\n716\n01:15:09.843 --> 01:15:12.804 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我想说的，长官，但一时口不择言…</c>\n\n717\n01:15:12.888 --> 01:15:18.143 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>口不择言？很显然，他故意的</c>\n\n718\n01:15:18.227 --> 01:15:21.271 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我试图了解他们，对他们友善些，长官</c>\n\n719\n01:15:21.355 --> 01:15:24.775 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>但他们合起伙来暗算我</c>\n\n720\n01:15:25.484 --> 01:15:30.322 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我靠近的时候\n他们总是喋喋不休，给我脸色看</c>\n\n721\n01:15:30.405 --> 01:15:33.325 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我会改正的 对他们要求严格</c>\n\n722\n01:15:33.408 --> 01:15:36.995 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你不该和水手交朋友 小伙子</c>\n\n723\n01:15:37.079 --> 01:15:41.333 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>这样他们会认为你无能，看不起你</c>\n\n724\n01:15:41.416 --> 01:15:45.170 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 你也不需高傲自满\n- 是，长官</c>\n\n725\n01:15:45.254 --> 01:15:47.506 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我很抱歉，长官</c>\n\n726\n01:15:47.589 --> 01:15:49.408 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你多大了？ 26 27？</c>\n\n727\n01:15:49.408 --> 01:15:51.009 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>下周五就30了，长官</c>\n\n729\n01:15:52.761 --> 01:15:56.014 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你两次报考尉官都没有通过</c>\n\n730\n01:15:56.098 --> 01:15:58.238 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我知道你是个不错的水手</c>\n\n731\n01:15:58.238 --> 01:16:00.978 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你不能一辈子都做见习军官</c>\n\n732\n01:16:01.061 --> 01:16:04.648 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是，长官，我会更加努力</c>\n\n733\n01:16:06.275 --> 01:16:09.695 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>听着，霍伦\n人需要被统领</c>\n\n734\n01:16:09.778 --> 01:16:11.780 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>权力</c>\n\n735\n01:16:11.864 --> 01:16:17.327 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>如果你有权力，就会获得他们的尊敬</c>\n\n736\n01:16:18.954 --> 01:16:22.457 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>缺了尊敬，就没了纪律</c>\n\n737\n01:16:23.625 --> 01:16:26.378 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是，长官，呃…</c>\n\n738\n01:16:26.461 --> 01:16:31.508 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>权力，尊敬…和纪律，长官</c>\n\n739\n01:16:35.470 --> 01:16:39.391 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>听着…这是一个很有挑战性的职业 霍伦</c>\n\n740\n01:16:40.475 --> 01:16:43.228 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>非常具有挑战性</c>\n\n741\n01:16:44.021 --> 01:16:46.899 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 我说完了\n- 是，长官</c>\n\n742\n01:16:50.152 --> 01:16:51.737 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我不是一个爱用鞭刑的船长</c>\n\n743\n01:16:51.820 --> 01:16:53.108 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>霍伦只是只替罪羊</c>\n\n744\n01:16:53.188 --> 01:16:57.576 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>他们把所有的厄运 无论是真假 都归咎于他</c>\n\n745\n01:16:57.659 --> 01:17:00.162 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>兰姆先生？能过来一下吗？</c>\n\n746\n01:17:00.245 --> 01:17:03.498 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>他们都累了，已经精疲力竭</c>\n\n747\n01:17:03.582 --> 01:17:06.460 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你对他们要求太高了</c>\n\n748\n01:17:06.543 --> 01:17:10.255 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>斯蒂芬 我以朋友的身份与你对话</c>\n\n749\n01:17:10.339 --> 01:17:14.593 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不是要你对我的指挥说三道四</c>\n\n750\n01:17:14.676 --> 01:17:20.182 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>等你心平气和的时候我再来，好吗？</c>\n\n751\n01:17:21.517 --> 01:17:25.270 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 你希望我怎么做？\n- 把酒都倒到海里去</c>\n\n752\n01:17:25.354 --> 01:17:28.815 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 禁酒？\n- 那格尔是喝醉才敢侮辱霍伦的</c>\n\n753\n01:17:28.899 --> 01:17:32.194 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>废止200年的特权与传统？</c>\n\n754\n01:17:32.277 --> 01:17:35.405 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我宁愿他们酩酊大醉 也不愿冒兵变的危险</c>\n\n755\n01:17:35.489 --> 01:17:37.783 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我对兵变比你了解得多</c>\n\n756\n01:17:37.866 --> 01:17:42.746 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>船员们离乡背井\n困在这木头牢笼里面几个月…</c>\n\n757\n01:17:42.829 --> 01:17:45.818 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你有权力保留自己的看法</c>\n\n758\n01:17:45.818 --> 01:17:49.618 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>但我再也不愿承受一次兵变了</c>\n\n759\n01:17:51.046 --> 01:17:55.342 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我不喜欢你这样描述当水手的生活\n这也是在贬低我</c>\n\n760\n01:17:55.425 --> 01:17:57.177 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你以为我想鞭打那格尔？</c>\n\n761\n01:17:57.261 --> 01:18:00.848 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>一个英勇解救同僚的水手</c>\n\n762\n01:18:00.931 --> 01:18:03.809 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我来下命令？</c>\n\n763\n01:18:03.892 --> 01:18:08.230 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你看不出吗？\n只有战斗精神才能把船员凝聚在一起</c>\n\n764\n01:18:08.313 --> 01:18:10.732 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>杰克 他只是没有敬礼</c>\n\n765\n01:18:10.816 --> 01:18:13.527 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>即使在自然界也是等级森严</c>\n\n766\n01:18:13.610 --> 01:18:16.608 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>自然界可没有鄙夷 没有…</c>\n\n767\n01:18:16.608 --> 01:18:18.858 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>人需要被统领！</c>\n\n768\n01:18:18.949 --> 01:18:21.493 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>虽然有时管理得不好 但这是必不可少的</c>\n\n769\n01:18:21.577 --> 01:18:25.873 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>暴君都拿这个当借口\n从尼禄到拿破仑</c>\n\n770\n01:18:25.956 --> 01:18:30.043 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我是反对压迫的 压迫会导致不幸和反抗</c>\n\n771\n01:18:30.127 --> 01:18:34.631 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>兄弟 你到这儿来兜售无政府主义是来错地方了</c>\n\n772\n01:18:37.467 --> 01:18:39.261 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>四</c>\n\n773\n01:18:40.762 --> 01:18:42.097 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>五</c>\n\n774\n01:18:44.433 --> 01:18:46.101 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>六</c>\n\n775\n01:18:47.352 --> 01:18:49.146 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>七</c>\n\n776\n01:18:50.439 --> 01:18:51.899 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>八</c>\n\n777\n01:18:52.649 --> 01:18:54.443 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>九</c>\n\n778\n01:18:56.778 --> 01:18:58.614 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>十</c>\n\n779\n01:18:59.781 --> 01:19:00.908 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>十一</c>\n\n780\n01:19:02.993 --> 01:19:04.953 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>十二</c>\n\n781\n01:19:07.956 --> 01:19:10.167 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>把他放下来</c>\n\n782\n01:19:34.149 --> 01:19:36.485 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>嘘 小点声</c>\n\n783\n01:20:30.622 --> 01:20:33.292 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>放下匕首 波义耳</c>\n\n784\n01:20:35.794 --> 01:20:38.380 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你还好吗 霍伦先生？</c>\n\n785\n01:20:38.463 --> 01:20:40.632 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>他没病 只是像往常一样想逃避工作</c>\n\n786\n01:20:40.716 --> 01:20:41.550 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>闭嘴！</c>\n\n787\n01:20:41.633 --> 01:20:44.720 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 你闭嘴\n- 让他好好休息休息</c>\n\n788\n01:20:44.803 --> 01:20:47.764 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 喝点水\n- 谢谢</c>\n\n789\n01:20:52.060 --> 01:20:54.396 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>长官 是霍伦先生</c>\n\n790\n01:21:01.486 --> 01:21:07.451 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>他身体没什么毛病 他只是认为受到了诅咒</c>\n\n791\n01:21:09.244 --> 01:21:12.873 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>水手什么都可以容忍 但不能容忍带来厄运的人</c>\n\n792\n01:21:13.582 --> 01:21:16.668 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>上帝啊 他也这么认为</c>\n\n793\n01:21:18.337 --> 01:21:21.798 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>书本上并不是什么都有 斯蒂芬</c>\n\n794\n01:21:28.305 --> 01:21:30.182 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是他 不是吗？</c>\n\n795\n01:21:32.809 --> 01:21:35.854 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>约拿</c>\n\n796\n01:21:35.938 --> 01:21:37.856 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>他就是祸根</c>\n\n797\n01:21:40.442 --> 01:21:43.695 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是他招来的厄运 你们看不见吗？</c>\n\n798\n01:21:43.779 --> 01:21:48.450 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>每次他当值 那只海盗船就出现</c>\n\n799\n01:21:51.870 --> 01:21:54.540 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不信你们等着瞧</c>\n\n800\n01:21:54.623 --> 01:21:59.586 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>今晚那鬼船一定会出现</c>\n\n801\n01:22:00.796 --> 01:22:05.551 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>它会把我们全都送进炼狱</c>\n\n802\n01:22:26.321 --> 01:22:28.615 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>霍伦先生</c>\n\n803\n01:22:28.699 --> 01:22:31.410 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>吓我一大跳</c>\n\n804\n01:22:33.871 --> 01:22:36.081 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>好点了吗？</c>\n\n805\n01:22:36.164 --> 01:22:39.668 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是的 好多了 谢谢</c>\n\n806\n01:22:51.013 --> 01:22:55.350 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>船长说明天就会有风了</c>\n\n807\n01:22:55.434 --> 01:22:57.519 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我相信</c>\n\n808\n01:23:26.465 --> 01:23:29.968 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你对我一直很友好</c>\n\n809\n01:23:37.100 --> 01:23:39.478 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>再见 布莱克尼</c>\n\n810\n01:24:47.796 --> 01:24:52.593 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>并不是每个人都能梦想成真\n成为自己想成为的人</c>\n\n811\n01:24:52.676 --> 01:24:55.637 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>但我们都是上帝创造的</c>\n\n812\n01:24:58.390 --> 01:25:02.686 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>如果有谁把霍伦先生往坏处想</c>\n\n813\n01:25:03.645 --> 01:25:06.315 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>说他的坏话</c>\n\n814\n01:25:08.066 --> 01:25:11.695 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不友善待他…</c>\n\n815\n01:25:12.988 --> 01:25:16.491 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我们祈求您的宽恕 上帝</c>\n\n816\n01:25:16.575 --> 01:25:18.744 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我们祈求他的宽恕</c>\n\n817\n01:25:34.510 --> 01:25:37.095 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>上帝显灵了，莫威先生！</c>\n\n818\n01:26:02.454 --> 01:26:04.873 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>且慢！</c>\n\n819\n01:26:18.637 --> 01:26:21.807 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 医生 你看到鸟了吗？\n- 什么鸟？</c>\n\n820\n01:26:21.890 --> 01:26:28.807 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>信天翁之类的 或者是大海鸥</c>\n\n821\n01:26:35.153 --> 01:26:39.074 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>来了 是我的 该死！</c>\n\n822\n01:26:39.147 --> 01:26:42.661 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>它在兜圈子 伙计们！</c>\n\n823\n01:26:49.835 --> 01:26:50.836 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>医生？</c>\n\n824\n01:26:50.919 --> 01:26:53.255 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>上帝！医生！医生！</c>\n\n825\n01:26:54.715 --> 01:26:59.595 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>实在抱歉 鸟飞得太低 我没看见你</c>\n\n826\n01:27:02.264 --> 01:27:05.475 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 卡拉米 叫希金斯来\n- 我没事 杰克</c>\n\n827\n01:27:19.031 --> 01:27:21.867 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>弹头带了一片碎布进去</c>\n\n828\n01:27:21.950 --> 01:27:26.955 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>如果不取出来 会感染的</c>\n\n829\n01:27:27.039 --> 01:27:29.041 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你行吗？</c>\n\n830\n01:27:29.124 --> 01:27:35.214 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我要看看医书 仔细观察图片</c>\n\n831\n01:27:35.297 --> 01:27:37.216 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>观察图片？</c>\n\n832\n01:27:37.299 --> 01:27:40.385 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>只是想多了解一些人体构造</c>\n\n833\n01:27:40.469 --> 01:27:47.059 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>如果在岸上会容易些 这里有点颠簸…</c>\n\n834\n01:27:47.142 --> 01:27:49.645 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我会搞定的</c>\n\n835\n01:28:14.086 --> 01:28:17.756 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>地平线发现帆影，长官！\n正向西航行</c>\n\n836\n01:28:18.340 --> 01:28:21.176 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不能肯定 但我们相信是它</c>\n\n837\n01:28:25.180 --> 01:28:27.182 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>最好还是…</c>\n\n838\n01:28:28.517 --> 01:28:30.602 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>再见</c>\n\n839\n01:28:48.871 --> 01:28:52.958 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>没错 是那条法国船</c>\n\n840\n01:29:00.549 --> 01:29:03.635 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我们要进入战斗岗位吗 长官？</c>\n\n841\n01:29:42.090 --> 01:29:44.551 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>上岸不会是因为我吧！</c>\n\n842\n01:29:44.635 --> 01:29:49.765 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不是为了你 我只是想上来活动活动腿脚</c>\n\n843\n01:29:51.517 --> 01:29:53.894 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>慢点</c>\n\n844\n01:30:00.692 --> 01:30:04.530 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>绳子拉紧</c>\n\n845\n01:30:04.613 --> 01:30:07.866 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>每20码布了一个哨卡</c>\n\n846\n01:30:18.919 --> 01:30:21.505 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 准备好了吗？\n- 是的 长官</c>\n\n847\n01:30:21.588 --> 01:30:23.966 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不</c>\n\n848\n01:30:24.633 --> 01:30:27.553 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我自己来</c>\n\n849\n01:30:33.058 --> 01:30:36.144 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>没事的话 我在外面等</c>\n\n850\n01:30:36.228 --> 01:30:39.314 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>多一双镇定手就多一份成功的把握</c>\n\n851\n01:30:39.398 --> 01:30:44.862 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>前提是你经受得住\n这种血腥场面</c>\n\n852\n01:30:45.320 --> 01:30:53.161 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>亲爱的医生 我遇到伤员无数</c>\n\n853\n01:30:53.745 --> 01:30:55.914 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>那很好</c>\n\n854\n01:30:55.998 --> 01:30:58.537 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>把手放到我的腹部</c>\n\n855\n01:30:58.617 --> 01:31:01.086 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我要你按的时候 你就紧紧按住</c>\n\n856\n01:31:01.170 --> 01:31:04.673 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>希金斯 给我手术刀</c>\n\n857\n01:31:12.097 --> 01:31:14.349 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>佩丁 镜子放好</c>\n\n858\n01:31:27.613 --> 01:31:30.115 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>给我探针 希金斯先生</c>\n\n859\n01:31:31.533 --> 01:31:33.577 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>药签</c>\n\n860\n01:31:43.629 --> 01:31:45.714 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>好了</c>\n\n861\n01:31:48.634 --> 01:31:51.845 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>希金斯先生 把我的肋骨撑起来</c>\n\n862\n01:31:54.723 --> 01:31:58.936 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>抓牢了…用牵开器</c>\n\n863\n01:32:02.397 --> 01:32:04.650 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>对了</c>\n\n864\n01:32:04.733 --> 01:32:06.652 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>撑起来</c>\n\n865\n01:32:06.735 --> 01:32:08.153 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>撑起来</c>\n\n866\n01:32:21.291 --> 01:32:23.919 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>药签 杰克，我看不见</c>\n\n867\n01:32:28.257 --> 01:32:31.260 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你没事吧？</c>\n\n868\n01:32:41.270 --> 01:32:43.355 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>有了</c>\n\n869\n01:32:54.992 --> 01:32:57.286 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>再加点力</c>\n\n870\n01:33:08.130 --> 01:33:10.799 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 行了吗？\n- 是的 先生</c>\n\n871\n01:33:11.550 --> 01:33:13.760 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>会愈合得很好的</c>\n\n872\n01:33:13.844 --> 01:33:15.721 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>感谢上帝</c>\n\n873\n01:34:01.558 --> 01:34:03.352 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>太好了</c>\n\n874\n01:34:11.026 --> 01:34:12.819 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>先生 先生！</c>\n\n875\n01:34:12.903 --> 01:34:16.782 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 这些是佩丁和我帮您采集的\n- 真的吗？</c>\n\n876\n01:34:16.865 --> 01:34:20.452 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>每种甲虫都栖息在不同种的植物上</c>\n\n877\n01:34:20.536 --> 01:34:22.996 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>佩丁那个跑掉了</c>\n\n878\n01:34:23.080 --> 01:34:27.376 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>先生 我还做了些记录 看看吧！</c>\n\n879\n01:34:43.392 --> 01:34:47.396 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>布莱克尼先生 似乎你很有博物学方面的天赋</c>\n\n880\n01:34:47.479 --> 01:34:54.361 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>先生 也许我可以像您一样 做个博物学者兼战士</c>\n\n881\n01:34:56.572 --> 01:34:59.908 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>可我发现 你似乎兼顾得还不够好</c>\n\n882\n01:34:59.992 --> 01:35:01.034 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是的</c>\n\n883\n01:35:01.118 --> 01:35:03.495 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>先生 你可以站起来了吗？</c>\n\n884\n01:35:03.579 --> 01:35:05.697 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>布莱克尼先生 你也是医生吗？</c>\n\n885\n01:35:05.697 --> 01:35:07.040 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不是 先生</c>\n\n886\n01:35:07.124 --> 01:35:10.502 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是的 你不是 佩丁 扶我一把</c>\n\n887\n01:35:17.009 --> 01:35:21.430 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>船长打算在这儿待多久 你知道吗？</c>\n\n888\n01:35:23.307 --> 01:35:25.767 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 也许一周吧\n- 一周？</c>\n\n889\n01:35:25.851 --> 01:35:29.897 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 不着急\n- 我们不是要追西班牙人吗？</c>\n\n890\n01:35:29.980 --> 01:35:32.900 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我不能肯定我们看见的就是地狱神号</c>\n\n891\n01:35:32.983 --> 01:35:38.030 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>即使是的话 也已经走得很远了 追不上了</c>\n\n892\n01:35:38.113 --> 01:35:43.285 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不 我们应该在于法国媾和之前回去\n但愿不会这样</c>\n\n893\n01:35:46.872 --> 01:35:50.292 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我怕我这辈子都无法报答你</c>\n\n894\n01:35:50.375 --> 01:35:53.057 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>胡说 不如以我的名字命名一种灌木吧</c>\n\n895\n01:35:53.057 --> 01:35:55.589 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>一种多刺 不容易连根拔起的灌木</c>\n\n896\n01:35:55.672 --> 01:36:00.385 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我会以你的名字\n命名一种巨龟</c>\n\n897\n01:36:00.469 --> 01:36:03.180 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>奥布里陆龟</c>\n\n898\n01:36:44.888 --> 01:36:48.267 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>收拾好东西 要出发了</c>\n\n899\n01:36:48.350 --> 01:36:51.520 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 回营地吗？\n- 不 我们去岛另一边</c>\n\n900\n01:36:51.603 --> 01:36:53.480 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>但 先生 那起码有10英里远</c>\n\n901\n01:36:53.564 --> 01:36:56.057 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>所以不能在耽误一分一秒了</c>\n\n902\n01:36:56.191 --> 01:36:59.152 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我就是在那儿发现不能飞的鸬鹚的</c>\n\n903\n01:36:59.236 --> 01:37:01.113 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>来吧</c>\n\n904\n01:37:12.082 --> 01:37:15.043 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>7英寸长</c>\n\n905\n01:37:16.044 --> 01:37:18.046 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>4英寸粗</c>\n\n906\n01:37:18.130 --> 01:37:20.716 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>15英寸长的脖子</c>\n\n907\n01:37:21.758 --> 01:37:26.054 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>最宽的地方有…6英寸</c>\n\n908\n01:37:32.144 --> 01:37:35.689 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>佩丁 用手抓 他们不咬人的</c>\n\n909\n01:37:35.772 --> 01:37:38.066 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>这个不错</c>\n\n910\n01:37:39.776 --> 01:37:42.487 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>小心点抓它们</c>\n\n911\n01:37:43.155 --> 01:37:46.033 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>先生 我们该回去了</c>\n\n912\n01:37:46.116 --> 01:37:49.847 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>将在外君命有所不受 布莱克尼先生</c>\n\n913\n01:37:49.857 --> 01:37:51.663 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我得找到那鸬鹚</c>\n\n914\n01:37:51.747 --> 01:37:54.374 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>它一定是不会飞的</c>\n\n915\n01:37:54.458 --> 01:37:58.253 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你可以作为共同发现者\n和我出席皇家学会晚宴</c>\n\n916\n01:39:22.045 --> 01:39:23.547 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>布莱克尼先生</c>\n\n917\n01:39:38.729 --> 01:39:41.023 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>先生 我们得抓紧时间了</c>\n\n918\n01:39:43.233 --> 01:39:48.937 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>佩丁 你背先生 把东西都放下</c>\n\n919\n01:39:52.451 --> 01:39:55.162 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>打开笼子</c>\n\n920\n01:40:09.635 --> 01:40:11.367 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>全体船员 起锚！</c>\n\n921\n01:40:11.367 --> 01:40:14.515 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>艾伦先生 我会让她右舷受风</c>\n\n922\n01:40:14.598 --> 01:40:17.809 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>把这些大家伙装上船</c>\n\n923\n01:40:17.893 --> 01:40:21.980 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>巴瑞特·邦登，向上风转舵</c>\n\n924\n01:40:23.899 --> 01:40:27.486 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>他在我们前面两个小时路程远 向南去了</c>\n\n925\n01:40:27.569 --> 01:40:31.240 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>他一定是去查尔斯国王岛 去补充水</c>\n\n926\n01:40:31.323 --> 01:40:38.330 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>如果我们跟上她 我是说要干掉她\n我们得隐形才行</c>\n\n927\n01:40:39.748 --> 01:40:42.668 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>转帆向右舷！</c>\n\n928\n01:40:51.927 --> 01:40:55.055 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>斯蒂芬 找到你要找的鸟了吗？</c>\n\n929\n01:40:55.138 --> 01:40:59.142 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是的 但是我抓不到</c>\n\n930\n01:40:59.852 --> 01:41:02.855 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我最大的发现就是你追的那条船</c>\n\n931\n01:41:02.938 --> 01:41:07.943 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是啊 我很抱歉不得不让你丢下你的标本</c>\n\n932\n01:41:08.026 --> 01:41:14.032 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>实际上 布莱克尼先生和我有一个有趣的发现</c>\n\n933\n01:41:14.116 --> 01:41:16.785 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是吗？</c>\n\n934\n01:41:16.869 --> 01:41:19.079 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>让我猜猜 树枝？</c>\n\n935\n01:41:26.128 --> 01:41:28.380 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>告诉他 布莱克尼先生</c>\n\n936\n01:41:28.463 --> 01:41:31.800 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 是一种很罕见的竹节虫\n- 竹节虫？</c>\n\n937\n01:41:31.884 --> 01:41:38.390 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>能伪装成树枝躲避它的天敌</c>\n\n938\n01:42:30.692 --> 01:42:32.945 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>海上竹节虫 医生</c>\n\n939\n01:42:33.028 --> 01:42:35.517 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>起码在饥肠辘辘的人眼里是的</c>\n\n940\n01:42:35.527 --> 01:42:38.033 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>看他是不是有这么大的胃口</c>\n\n941\n01:42:38.116 --> 01:42:42.454 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我决定今后多多关注自然</c>\n\n942\n01:42:42.538 --> 01:42:47.125 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我还真不知道研究自然还有助于提高海军战术</c>\n\n943\n01:42:47.209 --> 01:42:49.169 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>哦 我明白了</c>\n\n944\n01:42:49.253 --> 01:42:52.381 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>把捕猎者骗过来 收紧罗网</c>\n\n945\n01:42:52.464 --> 01:42:53.966 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 杰克？\n- 什么</c>\n\n946\n01:42:54.049 --> 01:42:56.885 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你才是捕猎者</c>\n\n947\n01:42:58.136 --> 01:43:03.225 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>隐蔽 左舷开阔出</c>\n\n948\n01:43:03.308 --> 01:43:05.227 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是艘护卫舰</c>\n\n949\n01:43:05.310 --> 01:43:08.522 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>妈的 你眼睛真好 巴瑞特</c>\n\n950\n01:43:08.605 --> 01:43:12.734 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 艾伦先生！再放点烟\n- 是长官！</c>\n\n951\n01:43:12.818 --> 01:43:15.445 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>他们会上当的</c>\n\n952\n01:43:26.290 --> 01:43:31.086 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>对了 弄干净了 那样就能飞得又远又直</c>\n\n953\n01:43:33.630 --> 01:43:36.758 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>都换上新火石</c>\n\n954\n01:43:45.851 --> 01:43:50.689 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>左舷炮组，卸下后炮车轮！</c>\n\n955\n01:43:55.194 --> 01:43:57.279 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>放下枪</c>\n\n956\n01:44:00.490 --> 01:44:04.119 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 奇利克，你也把衣服穿上\n- 哦，天呐！</c>\n\n957\n01:44:04.203 --> 01:44:07.122 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 汤姆？\n- 都准备好了 长官</c>\n\n958\n01:44:07.206 --> 01:44:09.557 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>很好 从现在开始 不要叫“长官”</c>\n\n959\n01:44:09.557 --> 01:44:11.919 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不要敬礼 不要吹口哨 不要敲钟</c>\n\n960\n01:44:12.002 --> 01:44:13.670 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是 长官</c>\n\n961\n01:44:13.754 --> 01:44:17.382 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>看来伪装有点困难</c>\n\n962\n01:44:18.300 --> 01:44:21.303 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>地狱神号上面会有大约30多个捕鲸人</c>\n\n963\n01:44:21.386 --> 01:44:24.765 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我们上船以后 卡拉米先生\n你负责带人去释放他们</c>\n\n964\n01:44:24.848 --> 01:44:26.907 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你觉得他准备好了吗 长官？</c>\n\n965\n01:44:26.907 --> 01:44:28.727 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你准备好了吗 汤姆？</c>\n\n966\n01:44:28.810 --> 01:44:31.563 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 他会扭转局势的\n- 是的 长官</c>\n\n967\n01:44:42.199 --> 01:44:44.451 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>它上钩了 我们转向</c>\n\n968\n01:44:44.535 --> 01:44:48.580 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>装做惊惶失措逃跑的样子 就像捕鲸人那样</c>\n\n969\n01:44:48.664 --> 01:44:51.083 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>在场诸位除外 霍格先生</c>\n\n970\n01:44:51.166 --> 01:44:53.085 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>快点 否则他们会看见我们的</c>\n\n971\n01:44:53.168 --> 01:44:57.339 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>厄哈特 别管了 快上来吧 穿上捕鲸人的衣服</c>\n\n972\n01:45:10.561 --> 01:45:14.523 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 祝贺你，代理三尉\n- 谢谢</c>\n\n973\n01:45:14.606 --> 01:45:16.608 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我听说我们要释放那些捕鲸人</c>\n\n974\n01:45:16.692 --> 01:45:19.319 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不包括你，你的岗位在后甲板</c>\n\n975\n01:45:19.403 --> 01:45:21.864 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>抱歉 威尔</c>\n\n976\n01:45:23.782 --> 01:45:29.204 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>假装无法稳定航线 引它跟上 不时转转舵</c>\n\n977\n01:45:30.038 --> 01:45:30.937 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>对不起 长官</c>\n\n978\n01:45:30.937 --> 01:45:33.000 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>摘下帽子 我们现在是捕鲸人</c>\n\n979\n01:45:33.083 --> 01:45:37.296 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>卡拉米先生说登船的人中没有我 我要说…</c>\n\n980\n01:45:37.379 --> 01:45:41.466 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我知道你要说什么 不行</c>\n\n981\n01:45:41.550 --> 01:45:45.971 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你带领你的炮手班 我们上船后 你来指挥这条船</c>\n\n982\n01:45:46.054 --> 01:45:50.392 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 明白吗？\n- 我指挥…谢谢 长官</c>\n\n983\n01:45:50.475 --> 01:45:52.978 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 回到你的岗位上去\n- 是 长官</c>\n\n984\n01:45:56.231 --> 01:45:59.401 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>把这个绑到右臂上 区分敌我！</c>\n\n985\n01:45:59.484 --> 01:46:02.154 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>戴维斯 是右边膀子</c>\n\n986\n01:46:02.237 --> 01:46:04.067 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是你剩下的那条 还是断了的？</c>\n\n987\n01:46:04.067 --> 01:46:05.949 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>别开玩笑了 戴维斯</c>\n\n988\n01:46:06.033 --> 01:46:09.828 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>把你们的领巾摘下来 扎到右臂上方</c>\n\n989\n01:46:09.912 --> 01:46:12.497 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>给船长让路</c>\n\n990\n01:46:13.916 --> 01:46:16.001 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>祝贺你 上尉</c>\n\n991\n01:46:16.084 --> 01:46:17.586 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>好了 小伙子们</c>\n\n992\n01:46:17.669 --> 01:46:20.005 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我知道你们勇敢非凡</c>\n\n993\n01:46:20.088 --> 01:46:23.884 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我也知道你们和我一样渴望战斗</c>\n\n994\n01:46:23.967 --> 01:46:27.554 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>但我们必须等他靠近才能张开罗网</c>\n\n995\n01:46:27.638 --> 01:46:29.681 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>这将是考验我们的勇气的时候了</c>\n\n996\n01:46:29.765 --> 01:46:33.852 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>但纪律和勇气同样重要</c>\n\n997\n01:46:33.936 --> 01:46:36.597 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>地狱神号不是那么好对付的</c>\n\n998\n01:46:36.597 --> 01:46:39.358 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>火力和人员都是我们的两倍</c>\n\n999\n01:46:39.441 --> 01:46:42.653 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>他们也很骁勇善战</c>\n\n1000\n01:46:44.488 --> 01:46:48.742 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>桅楼手，把帆脚索装得外行些\n别像正规海军</c>\n\n1001\n01:46:48.825 --> 01:46:51.495 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>看见信号就让帆漏风</c>\n\n1002\n01:46:51.578 --> 01:46:55.040 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>使船完全停下来</c>\n\n1003\n01:46:55.123 --> 01:46:58.710 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>炮手班 你们要立即出来 迅速架好炮</c>\n\n1004\n01:46:58.794 --> 01:47:01.627 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>由于没有后轮 你们可以朝上开火</c>\n\n1005\n01:47:01.627 --> 01:47:04.091 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>但没有后座力就没办法填弹</c>\n\n1006\n01:47:04.174 --> 01:47:09.471 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>所以你们只有一次开炮的机会</c>\n\n1007\n01:47:09.555 --> 01:47:11.577 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你们必须打中它的主桅杆</c>\n\n1008\n01:47:11.577 --> 01:47:14.393 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>这也是在考验你们炮弹的准确性</c>\n\n1009\n01:47:14.476 --> 01:47:22.767 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>然而 即使是被炮打中了 它也很危险 困兽尤斗</c>\n\n1010\n01:47:23.735 --> 01:47:25.737 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>霍华德上尉和陆战队员</c>\n\n1011\n01:47:25.821 --> 01:47:30.158 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>将从桅楼用回旋炮和步枪扫射其露天甲板</c>\n\n1012\n01:47:30.242 --> 01:47:33.245 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>他们将为我们登船创造机会</c>\n\n1013\n01:47:35.080 --> 01:47:38.625 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>他们想拿我们做战利品</c>\n\n1014\n01:47:38.709 --> 01:47:41.957 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>对他们来说 我们毫发无伤将更有价值</c>\n\n1015\n01:47:41.967 --> 01:47:45.424 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>他们的贪婪…是他们灭亡的导火索</c>\n\n1016\n01:47:47.259 --> 01:47:50.095 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>英帝国正遭受敌军侵犯的威胁</c>\n\n1017\n01:47:50.179 --> 01:47:52.077 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>虽然我们处于世界另一极</c>\n\n1018\n01:47:52.087 --> 01:47:54.349 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>这艘船便是代表我们的国家</c>\n\n1019\n01:47:55.976 --> 01:47:58.812 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>这艘船便是英帝国</c>\n\n1020\n01:48:02.024 --> 01:48:06.528 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>所以人人要各司其职 说话要简洁，动作要迅速</c>\n\n1021\n01:48:06.612 --> 01:48:09.990 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>到头来，胜利会是我们的</c>\n\n1022\n01:48:11.607 --> 01:48:15.907 align:middle line:85%,start position:50%,middle\n万岁！万岁！万岁！\n\n1023\n01:48:21.543 --> 01:48:23.247 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>抛高一点，以便让他们看的到</c>\n\n1024\n01:48:23.247 --> 01:48:24.463 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你好，医生</c>\n\n1025\n01:48:24.546 --> 01:48:25.881 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>杰克</c>\n\n1026\n01:48:25.964 --> 01:48:28.217 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 想来根雪茄吗？\n- 谢谢，不用了</c>\n\n1027\n01:48:28.300 --> 01:48:30.886 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>劳驾了，医生</c>\n\n1028\n01:48:32.304 --> 01:48:35.557 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 我擅自给您备了一杯，大夫\n- 谢谢你，奇利克</c>\n\n1029\n01:48:35.641 --> 01:48:40.270 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 里头多加了三颗方糖\n- 你真是个好人</c>\n\n1030\n01:49:35.117 --> 01:49:37.536 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 祝你好运，威尔\n- 祝你好运，彼得</c>\n\n1031\n01:49:39.371 --> 01:49:42.875 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 稍候见了\n- 你也一样</c>\n\n1032\n01:49:43.959 --> 01:49:47.629 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>稳住，各位，保持镇静</c>\n\n1033\n01:49:50.048 --> 01:49:53.635 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>英国捕鲸船塞伦号，这是地狱神号</c>\n\n1034\n01:49:53.719 --> 01:49:55.387 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 巴瑞特\n- 长官</c>\n\n1035\n01:49:55.470 --> 01:50:00.267 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你们绝无可能，也毫无机会\n我已经警告过你们了</c>\n\n1036\n01:50:00.350 --> 01:50:03.812 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>马上停船，否则我们将击沉你们的船</c>\n\n1037\n01:50:03.896 --> 01:50:07.316 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>英国捕鲸船，最后一次警告你们</c>\n\n1038\n01:50:07.399 --> 01:50:11.653 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>马上停船，否则我们将击沉你们</c>\n\n1039\n01:50:11.737 --> 01:50:13.989 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 放出来！\n- 放出来！</c>\n\n1040\n01:50:15.991 --> 01:50:19.745 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 旗帜升起来！\n- 是战舰！</c>\n\n1041\n01:50:21.163 --> 01:50:23.290 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>伸出去，各位！</c>\n\n1042\n01:50:23.373 --> 01:50:24.541 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>开炮！</c>\n\n1043\n01:50:25.751 --> 01:50:27.503 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>开炮！</c>\n\n1044\n01:50:36.428 --> 01:50:38.847 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>瞄准主桅，各位！</c>\n\n1045\n01:50:46.063 --> 01:50:48.482 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 让我过去\n- 开炮！</c>\n\n1046\n01:51:11.537 --> 01:51:14.287 align:middle line:85%,start position:50%,middle\n万岁！\n\n1047\n01:51:16.134 --> 01:51:18.220 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>左满舵！</c>\n\n1048\n01:51:18.929 --> 01:51:21.473 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>回正艏帆！升中桅帆！</c>\n\n1049\n01:51:21.557 --> 01:51:22.808 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>快拉！</c>\n\n1050\n01:51:23.934 --> 01:51:26.812 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>右侧炮台就位！</c>\n\n1051\n01:51:32.943 --> 01:51:35.279 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>全力炮击！</c>\n\n1052\n01:51:55.799 --> 01:51:58.760 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>靠过去！靠过去！</c>\n\n1053\n01:51:58.844 --> 01:52:01.513 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>桅杆倒了！我们无法停在旁边</c>\n\n1054\n01:52:01.597 --> 01:52:04.600 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>尽量避开残骸，我来掩护</c>\n\n1055\n01:52:04.683 --> 01:52:08.645 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 我这一组，去协助普灵斯先生！\n- 卷起中桅帆！</c>\n\n1056\n01:52:08.729 --> 01:52:11.732 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 幸运杰克万岁！\n- 万岁！</c>\n\n1057\n01:52:11.815 --> 01:52:14.443 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>抛钩子！</c>\n\n1058\n01:52:14.526 --> 01:52:16.904 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>架起登船板子！</c>\n\n1059\n01:52:19.114 --> 01:52:21.067 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我这组的，跟我来！</c>\n\n1060\n01:52:21.067 --> 01:52:24.203 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>为了英国，为了家园及为了奖赏！</c>\n\n1061\n01:52:24.870 --> 01:52:27.456 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>来吧，各位！</c>\n\n1062\n01:52:31.627 --> 01:52:33.712 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>安静！安静！</c>\n\n1063\n01:52:56.485 --> 01:52:58.487 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>看来任务成功了，长官</c>\n\n1064\n01:52:58.570 --> 01:53:00.280 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>地狱神号！</c>\n\n1065\n01:53:14.628 --> 01:53:15.796 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>射击！</c>\n\n1066\n01:53:32.563 --> 01:53:34.940 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>布莱克尼先生，用9磅炮！</c>\n\n1067\n01:53:35.023 --> 01:53:36.900 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>没错！</c>\n\n1068\n01:53:36.977 --> 01:53:38.057 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>开炮！</c>\n\n1069\n01:53:39.361 --> 01:53:41.613 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>继续前进，各位！继续前进！</c>\n\n1070\n01:54:30.787 --> 01:54:32.664 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>乔！</c>\n\n1071\n01:54:38.545 --> 01:54:40.130 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>手榴弹，准备！</c>\n\n1072\n01:54:50.349 --> 01:54:53.310 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>对方在瞄准我们的船身！</c>\n\n1073\n01:54:53.393 --> 01:54:56.063 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>会击沉我们的！炮口降低！</c>\n\n1074\n01:54:56.146 --> 01:54:58.190 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>佩丁，瞄准船尾！</c>\n\n1075\n01:54:58.273 --> 01:54:59.900 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>合力帮忙！</c>\n\n1076\n01:55:00.859 --> 01:55:02.986 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>退开点！</c>\n\n1077\n01:55:03.070 --> 01:55:04.863 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>开炮！</c>\n\n1078\n01:55:05.739 --> 01:55:08.116 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>拿好武器！准备跳帮！</c>\n\n1079\n01:55:09.535 --> 01:55:11.620 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>跟我来！</c>\n\n1080\n01:55:27.052 --> 01:55:28.762 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>上！</c>\n\n1081\n01:55:33.475 --> 01:55:37.563 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>船员们，跟我来！霍格先生\n在底下！快点来！</c>\n\n1082\n01:55:40.065 --> 01:55:43.819 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>信天翁！信天翁，听见我吗？</c>\n\n1083\n01:55:44.820 --> 01:55:46.822 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>回炮位！回炮位！</c>\n\n1084\n01:55:50.492 --> 01:55:52.744 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>波义耳，浇灭那门炮的引药！</c>\n\n1085\n01:56:28.030 --> 01:56:30.949 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>冲呀！快点！前进！</c>\n\n1086\n01:56:34.536 --> 01:56:37.164 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>兄弟们上！</c>\n\n1087\n01:56:52.717 --> 01:56:54.927 align:middle line:85%,start position:50%,middle\n不！不！不！\n\n1088\n01:57:08.570 --> 01:57:10.531 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 霍华德先生\n- 长官</c>\n\n1089\n01:57:10.614 --> 01:57:13.242 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 他们降下国旗了吗？\n- 我相信降下了</c>\n\n1090\n01:57:13.325 --> 01:57:16.995 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 有看到他们的船长吗？\n- 还没有，长官</c>\n\n1091\n01:57:17.079 --> 01:57:19.039 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 继续吧\n- 好的，长官</c>\n\n1092\n01:57:40.597 --> 01:57:43.977 align:middle line:85%,start position:50%,middle\n- 船长呢？\n- 在医务室\n\n1093\n01:58:01.737 --> 01:58:03.827 align:middle line:85%,start position:50%,middle\n医生？医生？\n\n1094\n01:58:03.907 --> 01:58:05.997 align:middle line:85%,start position:50%,middle\n我在这\n\n1095\n01:58:20.976 --> 01:58:23.353 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我是威格尼医生，先生</c>\n\n1096\n01:58:23.437 --> 01:58:26.231 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我对他已经尽力了</c>\n\n1097\n01:58:31.320 --> 01:58:35.407 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>船长死之前…吩咐我要把这个交给你</c>\n\n1098\n02:00:05.455 --> 02:00:08.375 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不，我来</c>\n\n1099\n02:00:22.139 --> 02:00:24.516 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>帮我一下好吗？</c>\n\n1100\n02:00:48.457 --> 02:00:50.250 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我们…</c>\n\n1101\n02:00:50.334 --> 02:00:54.379 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>在天上的天父，愿人都尊你的名为圣</c>\n\n1102\n02:00:54.463 --> 02:00:58.383 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>愿你的国降临，愿你的圣旨…</c>\n\n1103\n02:00:58.467 --> 02:01:00.761 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>…降临人间，如同还在天上</c>\n\n1104\n02:01:01.470 --> 02:01:04.223 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我们日用的饮食，今日赐给我们</c>\n\n1105\n02:01:04.306 --> 02:01:09.228 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>赦免我们的罪过 如同我们赦免我们的敌人</c>\n\n1106\n02:01:09.311 --> 02:01:13.398 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>让我们原离诱惑，救我们脱离凶恶</c>\n\n1107\n02:01:13.482 --> 02:01:15.442 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>因为国度…</c>\n\n1108\n02:01:15.526 --> 02:01:17.569 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>…权柄、荣耀，全是你的</c>\n\n1109\n02:01:17.653 --> 02:01:19.738 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>直到永远</c>\n\n1110\n02:01:19.821 --> 02:01:21.365 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>阿门</c>\n\n1111\n02:01:21.990 --> 02:01:25.452 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>罗伯特 加德纳，一等水兵</c>\n\n1112\n02:01:25.536 --> 02:01:29.414 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>詹姆斯 劳埃德，帆缆士</c>\n\n1113\n02:01:29.498 --> 02:01:32.501 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>罗伯特 堪普，一等水兵</c>\n\n1114\n02:01:33.710 --> 02:01:37.673 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>约翰 安东尼奥，航海士</c>\n\n1115\n02:01:38.882 --> 02:01:42.803 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>迈克尔·多德，一等水兵</c>\n\n1116\n02:01:44.346 --> 02:01:48.016 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>约瑟夫·那格尔，木匠副手</c>\n\n1117\n02:01:49.643 --> 02:01:52.896 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>约翰 艾伦，航海官</c>\n\n1118\n02:01:58.402 --> 02:02:00.362 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>彼得 米尔斯 卡拉米…</c>\n\n1119\n02:02:05.117 --> 02:02:07.369 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>上尉</c>\n\n1120\n02:02:09.788 --> 02:02:13.041 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>在此将他们的躯体葬入深海</c>\n\n1121\n02:02:13.125 --> 02:02:15.294 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>让他们的肉身腐朽</c>\n\n1122\n02:02:15.377 --> 02:02:17.346 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>当他们的躯体与大海溶为一体的时候</c>\n\n1123\n02:02:17.346 --> 02:02:19.214 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>这也是他们寻求重生机会的时候</c>\n\n1124\n02:02:19.298 --> 02:02:22.176 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>以期获得永生</c>\n\n1125\n02:02:22.259 --> 02:02:25.637 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>藉由主耶稣基督</c>\n\n1126\n02:02:25.721 --> 02:02:27.764 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>阿门</c>\n\n1127\n02:02:56.627 --> 02:02:58.921 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是我们的老朋友</c>\n\n1128\n02:03:53.308 --> 02:03:56.311 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>拜托递桶油漆下来</c>\n\n1129\n02:04:02.818 --> 02:04:05.066 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>长官，捕鲸船上的人全上船了</c>\n\n1130\n02:04:05.066 --> 02:04:06.989 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>那是最后一批陆战队员</c>\n\n1131\n02:04:07.072 --> 02:04:08.740 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>好，很好</c>\n\n1132\n02:04:08.824 --> 02:04:11.577 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我想我应该返回龟岛群岛</c>\n\n1133\n02:04:11.660 --> 02:04:15.414 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>补充点食物和水 给医生几天时间去找他的鸟</c>\n\n1134\n02:04:15.497 --> 02:04:16.748 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>非常好，长官</c>\n\n1135\n02:04:16.832 --> 02:04:20.252 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你要带地狱神号南下\n前往瓦尔帕莱索</c>\n\n1136\n02:04:20.335 --> 02:04:23.486 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>使俘虏宣誓后释放，船如有必要就整修</c>\n\n1137\n02:04:23.496 --> 02:04:25.536 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我们将在朴茨茅斯会合</c>\n\n1138\n02:04:25.674 --> 02:04:28.677 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我相信霍格先生来当航海官 会是个很好的选择</c>\n\n1139\n02:04:28.760 --> 02:04:33.473 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>总之，由你决定\n普灵斯船长</c>\n\n1140\n02:04:38.437 --> 02:04:40.522 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你的任命书</c>\n\n1141\n02:04:44.359 --> 02:04:47.070 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 谢谢，长官\n- 祝福你了，汤姆</c>\n\n1142\n02:04:47.154 --> 02:04:49.114 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>也祝福你，长官</c>\n\n1143\n02:04:54.912 --> 02:04:56.872 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 莫威先生？\n- 真替你高兴，长官</c>\n\n1144\n02:04:56.955 --> 02:04:59.625 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 祝你好运\n- 朴茨茅斯见了</c>\n\n1145\n02:04:59.708 --> 02:05:03.212 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>各位，为普灵斯船长\n欢呼！</c>\n\n1146\n02:05:03.286 --> 02:05:05.206 align:middle line:85%,start position:50%,middle\n各位，为普灵斯船长欢呼！\n\n1147\n02:05:05.666 --> 02:05:07.536 align:middle line:85%,start position:50%,middle\n- 万岁，万岁…\n- 万万岁！\n\n1148\n02:05:07.916 --> 02:05:10.756 align:middle line:85%,start position:50%,middle\n- 万岁，万岁…\n- 万万岁！\n\n1149\n02:05:10.886 --> 02:05:14.598 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 祝你好运，长官\n- 祝你好运，船长</c>\n\n1150\n02:05:30.614 --> 02:05:32.491 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>哦，又来了</c>\n\n1151\n02:05:32.574 --> 02:05:35.077 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>奇利克！奇利克！</c>\n\n1152\n02:05:35.160 --> 02:05:37.913 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>等它该准备好的时候自然会准备好</c>\n\n1153\n02:05:43.418 --> 02:05:46.421 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>等我知道船抵达岸边时 我会好好休息一番</c>\n\n1154\n02:05:46.505 --> 02:05:51.802 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>死伤众多，且只有那可怜\n不幸的希金斯去照顾他们</c>\n\n1155\n02:05:51.885 --> 02:05:55.556 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不过毕竟总比没有医生来的好</c>\n\n1156\n02:05:55.639 --> 02:05:57.956 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我见过对方的医生，还跟他讲过话</c>\n\n1157\n02:05:57.956 --> 02:06:00.435 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不，他几个月前就发高烧死了</c>\n\n1158\n02:06:00.519 --> 02:06:03.063 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 威格尼？\n- 嗯</c>\n\n1159\n02:06:11.016 --> 02:06:12.726 align:middle line:85%,start position:50%,middle\n啊\n\n1160\n02:06:14.616 --> 02:06:16.156 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>传话叫莫威先生过来</c>\n\n1161\n02:06:16.156 --> 02:06:18.412 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>莫威先生请到舰长主舱</c>\n\n1162\n02:06:18.495 --> 02:06:21.498 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>他们的“医生”给了我这把剑</c>\n\n1163\n02:06:22.499 --> 02:06:23.709 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>长官</c>\n\n1164\n02:06:23.792 --> 02:06:26.879 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>莫威先生，改变航向，朝东南东</c>\n\n1165\n02:06:26.962 --> 02:06:30.424 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>拦截地狱神号\n护送他们去瓦尔帕莱索</c>\n\n1166\n02:06:30.507 --> 02:06:33.385 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>遵命，长官，东南东</c>\n\n1167\n02:06:34.428 --> 02:06:37.222 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 威廉…\n- 长官？</c>\n\n1168\n02:06:37.306 --> 02:06:39.975 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 敲响战斗警报\n- 遵命，长官</c>\n\n1169\n02:06:45.063 --> 02:06:48.483 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>遵守军务的要求</c>\n\n1170\n02:06:52.226 --> 02:06:53.896 align:middle line:85%,start position:50%,middle\n啊\n\n1171\n02:06:55.991 --> 02:06:59.286 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>斯蒂芬…确定那种鸟不会飞吗？</c>\n\n1172\n02:06:59.369 --> 02:07:00.412 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>没错</c>\n\n1173\n02:07:01.538 --> 02:07:04.166 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>反正它哪儿也去不了</c>\n";
